import { useCallback, useEffect, useState } from 'react'
import { api, type DeployState, type Integration } from './api'
import { Sidebar } from './components/Sidebar'
import { Catalog } from './components/Catalog'
import { FlowView } from './components/FlowView'
import { Tracing } from './components/Tracing'
import { DarkModeIcon, LightModeIcon, SystemThemeIcon } from './icons'

const SIDEBAR_COLLAPSED_KEY = 'intropy.sidebar.collapsed'
const THEME_KEY = 'intropy.theme'

type View = 'catalog' | 'flow' | 'tracing'

const VIEWS: { id: View; label: string }[] = [
  { id: 'catalog', label: 'Integration Catalog' },
  { id: 'flow', label: 'Integration Flow' },
  { id: 'tracing', label: 'Tracing' },
]

// Theme preference cycles light → dark → system. "system" follows the OS,
// resolved to a concrete light/dark value that drives both data-theme (CSS)
// and the flow canvas colorMode.
type ThemePref = 'light' | 'dark' | 'system'
const THEME_ORDER: ThemePref[] = ['light', 'dark', 'system']
const THEME_META: Record<ThemePref, { Icon: typeof LightModeIcon; label: string }> = {
  light: { Icon: LightModeIcon, label: 'Light' },
  dark: { Icon: DarkModeIcon, label: 'Dark' },
  system: { Icon: SystemThemeIcon, label: 'System' },
}

function prefersDark(): boolean {
  return window.matchMedia('(prefers-color-scheme: dark)').matches
}

function resolveTheme(pref: ThemePref): 'light' | 'dark' {
  return pref === 'system' ? (prefersDark() ? 'dark' : 'light') : pref
}

export default function App() {
  const [integrations, setIntegrations] = useState<Integration[] | null>(null)
  const [selected, setSelected] = useState<string | null>(null)
  const [deployState, setDeployState] = useState<DeployState | null>(null)
  const [deployLoading, setDeployLoading] = useState(false)
  const [deployRefreshing, setDeployRefreshing] = useState(false)
  const [version, setVersion] = useState<string>('')
  const [error, setError] = useState<string | null>(null)
  const [collapsed, setCollapsed] = useState<boolean>(
    () => localStorage.getItem(SIDEBAR_COLLAPSED_KEY) === 'true',
  )
  const [view, setView] = useState<View>('catalog')
  const [theme, setTheme] = useState<ThemePref>(
    () => (localStorage.getItem(THEME_KEY) as ThemePref | null) ?? 'system',
  )
  const [resolvedTheme, setResolvedTheme] = useState<'light' | 'dark'>(() =>
    resolveTheme(theme),
  )

  useEffect(() => {
    localStorage.setItem(SIDEBAR_COLLAPSED_KEY, String(collapsed))
  }, [collapsed])

  // Apply the theme to <html> and track the resolved value. In system mode,
  // also follow live OS changes; explicit modes ignore them.
  useEffect(() => {
    localStorage.setItem(THEME_KEY, theme)
    const apply = () => {
      const resolved = resolveTheme(theme)
      document.documentElement.dataset.theme = resolved
      setResolvedTheme(resolved)
    }
    apply()
    if (theme !== 'system') return
    const mq = window.matchMedia('(prefers-color-scheme: dark)')
    mq.addEventListener('change', apply)
    return () => mq.removeEventListener('change', apply)
  }, [theme])

  const cycleTheme = () =>
    setTheme((t) => THEME_ORDER[(THEME_ORDER.indexOf(t) + 1) % THEME_ORDER.length])

  useEffect(() => {
    api
      .listIntegrations()
      .then(setIntegrations)
      .catch((e: unknown) => setError(errText(e)))
    api
      .health()
      .then((h) => setVersion(h.version))
      .catch(() => {})
  }, [])

  // Auto-select the first integration once the list loads.
  useEffect(() => {
    if (integrations && integrations.length > 0 && !selected) {
      setSelected(integrations[0].path)
    }
  }, [integrations, selected])

  // Deployment state loads on its own, because it costs its own thing: reading
  // it refreshes a GitOps checkout over the network, while the catalog entry
  // is local files plus a cached topology. Keeping them apart lets the page
  // render straight away.
  //
  // A failed lookup is not an error banner: the reason travels inside the state
  // and belongs in the Deployment section, next to the Refresh that retries it.
  useEffect(() => {
    if (!selected) {
      setDeployState(null)
      return
    }
    setDeployState(null)
    setDeployLoading(true)
    let current = true
    api
      .deployState(selected)
      .then((s) => {
        if (current) setDeployState(s)
      })
      .catch((e: unknown) => {
        if (current) setDeployState({ error: errText(e), readAt: new Date().toISOString() })
      })
      .finally(() => {
        if (current) setDeployLoading(false)
      })
    // Selecting another integration while this is in flight must not let the
    // slower answer land on the newer selection.
    return () => {
      current = false
    }
  }, [selected])

  const refreshDeploy = useCallback(() => {
    if (!selected) return
    setDeployRefreshing(true)
    api
      .refreshDeployState(selected)
      .then(setDeployState)
      .catch((e: unknown) =>
        setDeployState({ error: errText(e), readAt: new Date().toISOString() }),
      )
      .finally(() => setDeployRefreshing(false))
  }, [selected])

  return (
    <div className="app">
      <header className="topbar">
        <div className="brand">
          <span className="brand-mark" aria-hidden />
          <span className="brand-name">Intropy</span>
          <span className="brand-sub">dashboard</span>
        </div>
        <nav className="nav">
          {VIEWS.map((v) => (
            <button
              key={v.id}
              className={`nav-item${view === v.id ? ' active' : ''}`}
              onClick={() => setView(v.id)}
              aria-current={view === v.id ? 'page' : undefined}
            >
              {v.label}
            </button>
          ))}
        </nav>
        <div className="topbar-end">
          {version && <span className="version">{version}</span>}
          <ThemeToggle theme={theme} onCycle={cycleTheme} />
        </div>
      </header>

      <div className="layout">
        {view === 'catalog' && (
          <Sidebar
            integrations={integrations}
            selected={selected}
            onSelect={setSelected}
            collapsed={collapsed}
            onToggle={() => setCollapsed((c) => !c)}
          />
        )}
        <main className="content">
          {error && <div className="banner error">{error}</div>}
          {view === 'catalog' ? (
            <Catalog
              path={selected}
              deploy={{
                state: deployState,
                loading: deployLoading,
                refreshing: deployRefreshing,
                onRefresh: refreshDeploy,
              }}
            />
          ) : null}
          {view === 'flow' && (
            <FlowView selected={selected} onSelect={setSelected} theme={resolvedTheme} />
          )}
          {view === 'tracing' && <Tracing />}
        </main>
      </div>
    </div>
  )
}

// ThemeToggle cycles the theme preference. The current mode's glyph and a
// title communicate both the active choice and that clicking advances it.
function ThemeToggle({ theme, onCycle }: { theme: ThemePref; onCycle: () => void }) {
  const { Icon, label } = THEME_META[theme]
  return (
    <button
      type="button"
      className="theme-toggle"
      onClick={onCycle}
      title={`Theme: ${label} (click to change)`}
      aria-label={`Theme: ${label}. Click to change.`}
    >
      <Icon className="icon" aria-hidden />
    </button>
  )
}

function errText(e: unknown): string {
  return e instanceof Error ? e.message : String(e)
}
// Package dashboard serves the local Intropy integration dashboard: a small
// stdlib net/http server that exposes a JSON API over the integrations
// discovered under a workspace root and serves the embedded SPA that renders
// them.
//
// It changes nothing on disk except when asked: the flow view can start and
// stop a system's host locally (run.go — the one long-lived process the
// package supervises, parented to the dashboard's lifetime), and the template
// and system endpoints render scaffolds into the workspace the way the CLI
// would. What it runs read-only is two things, both on request rather than at
// startup: each system host's `graph` verb, for the topology the flow view
// draws, and the deploy status command, for what the catalog reports each
// environment is running. The second one refreshes the cached GitOps checkout
// and reads ArgoCD, so it is the only part of this package that touches the
// network — asked for one integration at a time, and reused until an explicit
// refresh.
//
// Deployment facts are never derived here. The command owns every refusal that
// matters — an unset gitopsRepo, a component name matching several, an
// environment nobody has onboarded — and its answers are passed through
// verbatim, so the dashboard cannot claim something the command line would not.
package dashboard

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"time"
)

// Options configures a dashboard server. The zero value is not usable; Root is
// required and Addr/Port select the listen address.
type Options struct {
	// Root is the workspace directory scanned for integrations.
	Root string
	// Addr is the host/interface to bind, e.g. "127.0.0.1". Empty binds all.
	Addr string
	// Port is the TCP port to bind. 0 asks the OS for a free port.
	Port int
	// OpenBrowser opens the dashboard URL in the default browser on start.
	OpenBrowser bool
	// Version is reported by GET /api/health.
	Version string
	// TemplateVersion pins the template library release the /api/templates
	// endpoints fetch and render against. Empty resolves the latest release.
	TemplateVersion string
	// Organization is the resolved config's customer, offered as the
	// ambient default for template organization parameters. A workspace
	// whose records already agree on an organization keeps its own.
	Organization string
	// Stdout and Stderr receive program output and diagnostics; both default
	// to the process streams when nil.
	Stdout io.Writer
	Stderr io.Writer
}

// shutdownTimeout bounds how long in-flight requests have to drain on Ctrl+C.
const shutdownTimeout = 5 * time.Second

// Serve starts the dashboard and blocks until ctx is cancelled (e.g. SIGINT)
// or the server fails. On cancellation it shuts down gracefully and returns
// nil; it returns a non-nil error only for a real startup or runtime failure.
func Serve(ctx context.Context, opts Options) error {
	if opts.Stdout == nil {
		opts.Stdout = os.Stdout
	}
	if opts.Stderr == nil {
		opts.Stderr = os.Stderr
	}
	root := opts.Root
	if root == "" {
		root = "."
	}
	// Resolve to an absolute path: the API mixes root-relative identifiers
	// with absolute on-disk results (a create's outputDir), and relPath can
	// only join the two when root itself is absolute.
	if abs, err := filepath.Abs(root); err == nil {
		root = abs
	}

	handler, api, err := newHandler(root, opts.Version, providers{
		topology: hostGraphProvider(root),
		deploy:   statusCommandProvider(opts.Version),
		templates: templatesProvider{
			version:   opts.TemplateVersion,
			userAgent: "intropy-cli/" + opts.Version,
		},
	})
	if err != nil {
		return fmt.Errorf("run: %w", err)
	}
	api.organization = opts.Organization

	addr := net.JoinHostPort(opts.Addr, fmt.Sprintf("%d", opts.Port))
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		return fmt.Errorf("run: cannot listen on %s: %w", addr, err)
	}

	url := displayURL(opts.Addr, ln.Addr())
	fmt.Fprintf(opts.Stderr, "Intropy dashboard running at %s\n", url)
	fmt.Fprintln(opts.Stderr, "Press Ctrl+C to stop.")

	if opts.OpenBrowser {
		if err := openBrowser(url); err != nil {
			fmt.Fprintf(opts.Stderr, "warning: could not open browser: %v\n", err)
		}
	}

	srv := &http.Server{Handler: handler}
	errCh := make(chan error, 1)
	go func() {
		err := srv.Serve(ln)
		if err != nil && !errors.Is(err, http.ErrServerClosed) {
			errCh <- err
			return
		}
		errCh <- nil
	}()

	select {
	case <-ctx.Done():
		fmt.Fprintln(opts.Stderr, "\nShutting down…")
		shutdownCtx, cancel := context.WithTimeout(context.Background(), shutdownTimeout)
		defer cancel()
		if err := srv.Shutdown(shutdownCtx); err != nil {
			api.shutdownRuns()
			return fmt.Errorf("run: shutdown: %w", err)
		}
		// Hosts started from the flow view are children of the dashboard:
		// they stop when it does.
		api.shutdownRuns()
		return nil
	case err := <-errCh:
		api.shutdownRuns()
		if err != nil {
			return fmt.Errorf("run: server error: %w", err)
		}
		return nil
	}
}

// displayURL builds a browser-friendly URL. It uses the actual bound port
// (important when Port was 0) and rewrites wildcard bind hosts to localhost.
func displayURL(host string, addr net.Addr) string {
	port := 0
	if tcp, ok := addr.(*net.TCPAddr); ok {
		port = tcp.Port
	}
	if host == "" || host == "0.0.0.0" || host == "::" {
		host = "localhost"
	}
	return fmt.Sprintf("http://%s", net.JoinHostPort(host, fmt.Sprintf("%d", port)))
}
package main

import (
	"fmt"
	"os"
	"os/signal"
	"syscall"

	"github.com/integrio-intropy/intropy-cli/internal/config"
	"github.com/integrio-intropy/intropy-cli/internal/dashboard"
	"github.com/spf13/cobra"
)

// dashboard serves the local integration dashboard. The HTTP server and
// JSON API live in internal/dashboard; this file is flag plumbing.
type dashboardFlags struct {
	port            int
	noBrowser       bool
	templateVersion string
}

var dashboardOpts dashboardFlags

var dashboardCmd = &cobra.Command{
	Use:   "dashboard [dir]",
	Short: "Launch the local integration dashboard",
	Long: "Start a local web dashboard that visualizes the integrations and systems scaffolded under dir " +
		"(default: the current directory) — their template, pinned source, version, scaffold values and " +
		"system topology. The flow view can also start and stop a system's host locally (dotnet run); " +
		"started hosts stop when the dashboard does. The dashboard is served from the CLI itself and " +
		"opens in your browser. Press Ctrl+C to stop.",
	Args: usageArgs(cobra.MaximumNArgs(1)),
	RunE: func(cmd *cobra.Command, args []string) error {
		root := "."
		if len(args) == 1 {
			root = args[0]
		}
		if info, err := os.Stat(root); err != nil {
			return fmt.Errorf("dashboard: %w", err)
		} else if !info.IsDir() {
			return newUsageErrorf("dashboard: %s is not a directory", root)
		}

		ctx, cancel := signal.NotifyContext(cmd.Context(), os.Interrupt, syscall.SIGTERM)
		defer cancel()

		return dashboard.Serve(ctx, dashboard.Options{
			Root:            root,
			Addr:            "127.0.0.1",
			Port:            dashboardOpts.port,
			OpenBrowser:     !dashboardOpts.noBrowser,
			Version:         version,
			TemplateVersion: dashboardOpts.templateVersion,
			Organization:    resolvedOrganization(),
			Stdout:          cmd.OutOrStdout(),
			Stderr:          cmd.ErrOrStderr(),
		})
	},
}

// resolvedOrganization reads the config's organization for the
// dashboard's template suggestions. A config that cannot be read yields
// "": the dashboard serves workspaces without one, and template forms
// simply offer no organization candidate.
func resolvedOrganization() string {
	cfg, err := config.Load()
	if err != nil {
		return ""
	}
	return cfg.Resolve(config.Flags{}).Organization
}

func init() {
	f := dashboardCmd.Flags()
	f.IntVarP(&dashboardOpts.port, "port", "p", 8730, "port to bind (0 picks a free port)")
	f.BoolVar(&dashboardOpts.noBrowser, "no-browser", false, "do not open the dashboard in a browser")
	f.StringVar(&dashboardOpts.templateVersion, "template-version", "", flagUsageTemplateVer)
	markPreview(dashboardCmd)
	rootCmd.AddCommand(dashboardCmd)
}

export function FlowView({ selected, onSelect, theme }: Props) {
  const [graph, setGraph] = useState<IntegrationDetail[] | null>(null)
  const [systemList, setSystemList] = useState<SystemInfo[] | null>(null)
  const [report, setReport] = useState<TopologyReport | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [refreshing, setRefreshing] = useState(false)
  const [system, setSystem] = useState<string | null>(null)
  const [workspaceName, setWorkspaceName] = useState<string | null>(null)
  const [nodes, setNodes, onNodesChange] = useNodesState<Node>([])
  // What the inspector panel shows: a clicked topic or port node.
  const [inspect, setInspect] = useState<FlowSelection | null>(null)
  // A clicked placeholder slot: which block kind the create drawer offers.
  const [draft, setDraft] = useState<SlotKind | null>(null)
  // A clicked seed action: which component the seed drawer targets.
  const [seeding, setSeeding] = useState<string | null>(null)
  // The banner's host re-assembly (sys update / sys create) in flight, and
  // the force checkbox a 409 offers, as the create and seed drawers do.
  const [syncing, setSyncing] = useState(false)
  const [syncError, setSyncError] = useState<string | null>(null)
  const [syncErrorStatus, setSyncErrorStatus] = useState<number | null>(null)
  const [syncForce, setSyncForce] = useState(false)
  // The selected system's host process, as the dashboard last knew it, plus
  // the start/stop click in flight and the run log panel's visibility.
  const [run, setRun] = useState<RunState | null>(null)
  const [runBusy, setRunBusy] = useState(false)
  const [runError, setRunError] = useState<string | null>(null)
  const [logsOpen, setLogsOpen] = useState(false)

  // A different system means different topics/ports — drop the inspector,
  // any half-open create drawer, and stale sync/run errors.
  useEffect(() => {
    setInspect(null)
    setDraft(null)
    setSeeding(null)
    setSyncError(null)
    setSyncErrorStatus(null)
    setSyncForce(false)
    setRunError(null)
  }, [system])

  useEffect(() => {
    const fail = (e: unknown) => setError(e instanceof Error ? e.message : String(e))
    api.flow().then(setGraph).catch(fail)
    api.systems().then(setSystemList).catch(fail)
    // The workspace pseudo-system labels itself after the served folder;
    // a miss keeps the generic fallback rather than failing the view.
    api
      .health()
      .then((h) => setWorkspaceName(h.workspace || null))
      .catch(() => {})
    // The first topology fetch runs each host's graph verb (a dotnet build),
    // so this request can take a while — the loading state covers it.
    api.topologies().then(setReport).catch(fail)
  }, [])

  const refresh = () => {
    setRefreshing(true)
    api
      .refreshTopologies()
      .then(setReport)
      .catch((e: unknown) => setError(e instanceof Error ? e.message : String(e)))
      .finally(() => setRefreshing(false))
  }

  const topologies = useMemo(() => report?.topologies ?? [], [report])

  // The dropdown lists every system present, with an integration count. When
  // a declared topology covers a group its system name is the authoritative
  // label, overriding the folder-derived one. Systems that end up sharing a
  // label are qualified with their directory so the options stay tellable
  // apart — the underlying keys are always distinct.
  const systems = useMemo<ComboOption[]>(() => {
    if (!graph) return []
    const opts = new Map<string, ComboOption>()
    for (const it of graph) {
      const key = systemKey(it)
      const opt = opts.get(key) ?? { value: key, label: systemLabel(it), count: 0 }
      opt.count = (opt.count ?? 0) + 1
      opts.set(key, opt)
    }
    // Declared systems with no blocks yet (a host-only scaffold) still get an
    // option — they render as the empty slot skeleton, the create surface's
    // best onboarding moment.
    for (const s of systemList ?? []) {
      if (!opts.has(s.path)) opts.set(s.path, { value: s.path, label: s.name, count: 0 })
    }
    // A workspace with nothing in it at all still offers the workspace
    // pseudo-system, so the canvas opens as the fillable slot skeleton
    // instead of a dead end — the first block scaffolds at the root.
    if (opts.size === 0) {
      opts.set(WORKSPACE_KEY, { value: WORKSPACE_KEY, label: 'Workspace', count: 0 })
    }
    // The pseudo-system labels itself after the served folder; a topology
    // declared at the root (below) still overrides with its system name.
    const ws = opts.get(WORKSPACE_KEY)
    if (ws && workspaceName) ws.label = workspaceName
    for (const opt of opts.values()) {
      const t = topologyFor(opt.value, topologies)
      if (t) opt.label = t.system
    }
    const byLabel = new Map<string, ComboOption[]>()
    for (const opt of opts.values()) {
      byLabel.set(opt.label, [...(byLabel.get(opt.label) ?? []), opt])
    }
    for (const dup of byLabel.values()) {
      if (dup.length > 1) for (const opt of dup) opt.label = `${opt.label} (${opt.value})`
    }
    return [...opts.values()].sort((a, b) => a.label.localeCompare(b.label))
  }, [graph, systemList, topologies, workspaceName])

  // Default to the first system once data lands.
  useEffect(() => {
    if (system === null && systems.length > 0) setSystem(systems[0].value)
  }, [systems, system])

  const items = useMemo(
    () => (graph && system ? graph.filter((it) => systemKey(it) === system) : []),
    [graph, system],
  )

  // Only a declared topology contributes wiring — there is no inferred
  // fallback. A system without one still renders: a synthetic empty record
  // makes every scaffolded block a ghost and shows the slot skeleton, so a
  // brand-new system is a fillable shape instead of a dead end.
  const declared = useMemo(
    () => (system ? topologyFor(system, topologies) : undefined),
    [system, topologies],
  )
  const effective = useMemo<Topology | undefined>(() => {
    if (declared) return declared
    if (!system) return undefined
    const label = systems.find((o) => o.value === system)?.label ?? system
    return {
      path: system === WORKSPACE_KEY ? '.' : system,
      apiVersion: 'topology.intropy.io/v1',
      system: label,
    }
  }, [declared, system, systems])
  const built = useMemo(
    () =>
      effective
        ? buildDeclaredGraph(effective, items)
        : { nodes: [] as Node[], edges: [] as Edge[], ghosts: [] as IntegrationDetail[] },
    [effective, items],
  )

  // Mark the nodes that offer seeding. A declared extractor (kind maps to
  // data flow "in") is 'ready' — the drawer resolves its in-ports and dev
  // folders. A ghost identified as an extractor is 'ghost' — a disabled,
  // explained button: without declared wiring there is no port to seed.
  // Ghosts of unknown kind get nothing: the data model cannot always tell
  // "known extractor, undeclared" from "unknown kind", so it errs on
  // absence rather than a misleading disabled button.
  const seededNodes = useMemo(() => {
    const ready = new Set(
      (effective?.components ?? [])
        .filter((c) => dataFlowFor(c.kind) === 'in')
        .map((c) => c.name),
    )
    const ghostPaths = new Set(
      built.ghosts
        .filter(
          (g) => (g.dataFlow ?? (g.blockKind ? dataFlowFor(g.blockKind) : undefined)) === 'in',
        )
        .map((g) => g.path),
    )
    return built.nodes.map((n) => {
      if (n.type !== 'integration') return n
      const d = n.data as IntNodeData
      const seed = d.ghost
        ? ghostPaths.has(n.id)
          ? ('ghost' as const)
          : undefined
        : ready.has(d.name)
          ? ('ready' as const)
          : undefined
      return seed === d.seed ? n : { ...n, data: { ...d, seed } }
    })
  }, [built, effective])
  useEffect(() => setNodes(seededNodes), [seededNodes, setNodes])

  // After a create, the new scaffold shows up as a ghost through the normal
  // join — the placeholder→ghost transition is a data refresh, not UI state.
  const handleCreated = () => {
    setDraft(null)
    api.flow().then(setGraph).catch((e: unknown) =>
      setError(e instanceof Error ? e.message : String(e)),
    )
  }

  const sysDir = system === WORKSPACE_KEY ? '.' : system
  const hasHost = (systemList ?? []).some((s) => s.path === sysDir)

  // Track the selected system's host process. Poll on a steady interval
  // while a host is selected so a start, stop, or crash surfaces without the
  // user clicking anything; start/stop clicks also set the state directly
  // from their response, so the interval only ever reconciles.
  useEffect(() => {
    if (!sysDir || !hasHost) {
      setRun(null)
      return
    }
    let alive = true
    const pull = () =>
      api
        .runState(sysDir)
        .then((st) => {
          if (alive) setRun(st)
        })
        .catch(() => {})
    pull()
    const tick = setInterval(pull, 2000)
    return () => {
      alive = false
      clearInterval(tick)
    }
  }, [sysDir, hasHost])

  const runClick = () => {
    if (!sysDir || runBusy) return
    setRunBusy(true)
    setRunError(null)
    const call = run?.running ? api.stopSystem(sysDir) : api.startSystem(sysDir)
    call
      .then(setRun)
      .catch((e: unknown) => setRunError(e instanceof Error ? e.message : String(e)))
      .finally(() => setRunBusy(false))
  }

  // Re-assemble the host (sys update, or sys create when the system has no
  // host yet), then refresh the topology so the ghosts turn into declared
  // nodes — the banner's one click that closes the create loop.
  const syncHost = (force = false) => {
    if (!sysDir) return
    setSyncing(true)
    setSyncError(null)
    setSyncErrorStatus(null)
    api
      .syncSystem(sysDir, force)
      .then((resp) => {
        setSyncing(false)
        setSyncForce(false)
        refresh()
        // The create branch writes a new host scaffold: pick it up so the
        // picker and the button label agree with the workspace again.
        api.systems().then(setSystemList).catch(() => {})
        if (resp.action === 'create' && resp.hostDir) {
          // A new host changes every sibling's systemPath (the group key),
          // so the stale flow data would leave a duplicate picker entry.
          // Re-fetch and follow the selection onto the host's system dir.
          api.flow().then(setGraph).catch(() => {})
          const slash = resp.hostDir.lastIndexOf('/')
          setSystem(slash >= 0 ? resp.hostDir.slice(0, slash) : '.')
        }
      })
      .catch((e: unknown) => {
        setSyncing(false)
        setSyncError(e instanceof Error ? e.message : String(e))
        setSyncErrorStatus(
          e instanceof Error && 'status' in e && typeof e.status === 'number'
            ? e.status
            : null,
        )
      })
  }

  // Reflect the shared selection without disturbing dragged positions.
  useEffect(() => {
    setNodes((ns) =>
      ns.map((n) =>
        n.type === 'integration'
          ? { ...n, data: { ...n.data, selected: n.id === selected } }
          : n,
      ),
    )
  }, [selected, setNodes])

  if (error) {
    return <div className="banner error">{error}</div>
  }
  if (!graph || report === null) {
    return <p className="empty">Loading… (building system hosts on first run)</p>
  }

  return (
    <div className="flow-view">
      <div className="flow-toolbar">
        <span className="flow-toolbar-label">System</span>
        <Combobox
          value={system}
          options={systems}
          onChange={setSystem}
          placeholder="Select a system…"
        />
        {hasHost && (
          <button
            type="button"
            className={`flow-run${run?.running ? ' running' : ''}`}
            onClick={runClick}
            disabled={runBusy}
            title={
              run?.running
                ? 'Stop the system host (SIGTERM the dotnet run process group)'
                : 'Start the system host locally (dotnet run --project <host>)'
            }
          >
            {runBusy
              ? run?.running
                ? 'Stopping…'
                : 'Starting…'
              : run?.running
                ? 'Stop'
                : 'Start'}
          </button>
        )}
        {hasHost && run?.running && (
          <span
            className={`flow-run-status${run.ready ? '' : ' starting'}`}
            title={`pid ${run.pid} · started ${run.startedAt}`}
          >
            <span className="flow-run-dot" />
            {run.ready ? 'running' : 'starting'}
          </span>
        )}
        {hasHost && run && !run.running && run.exitError && (
          <span className="flow-run-status crashed" title={run.exitError}>
            <span className="flow-run-dot" />
            exited
          </span>
        )}
        {hasHost && run && run.logs.length > 0 && (
          <button
            type="button"
            className="flow-logs-toggle"
            onClick={() => setLogsOpen((o) => !o)}
            title="Show the host's stdout/stderr tail"
          >
            {logsOpen ? 'Hide logs' : 'Logs'}
          </button>
        )}
        <button
          type="button"
          className="flow-refresh"
          onClick={refresh}
          disabled={refreshing}
          title="Re-run each system host's graph verb"
        >
          {refreshing ? 'Refreshing…' : 'Refresh topology'}
        </button>
      </div>
      {runError && <div className="banner error">{runError}</div>}
      {logsOpen && run && (
        <pre className="flow-run-logs">
          {run.logs.join('\n') || 'no output yet'}
        </pre>
      )}
      {report.errors?.length ? (
        <div className="banner error">
          {report.errors.map((e) => (
            <div key={e}>{e}</div>
          ))}
        </div>
      ) : null}
      {effective && !declared && (
        <div className="banner hint">
          No declared topology for this system yet — its components render
          from their scaffold records until the host's graph verb declares
          them.
        </div>
      )}
      {built.ghosts.length > 0 && (
        <div className="banner hint">
          {built.ghosts.length === 1
            ? '1 scaffolded component is'
            : `${built.ghosts.length} scaffolded components are`}{' '}
          not in the declared topology yet.
          <button
            type="button"
            className="flow-refresh"
            onClick={() => syncHost()}
            disabled={syncing || refreshing}
            title={
              hasHost
                ? 'Fold the new components into the system host (sys update), then refresh the topology'
                : 'Assemble a system host from the scaffolds (sys create), then refresh the topology'
            }
          >
            {syncing
              ? hasHost
