              : hasHost
                ? 'Update host & refresh'
                : 'Create host & refresh'}
          </button>
        </div>
      )}
      {syncError && (
        <div className="banner error">
          {syncError}
          {syncErrorStatus === 409 && (
            <div className="banner-actions">
              <label className="force-row">
                <input
                  type="checkbox"
                  checked={syncForce}
                  onChange={(e) => setSyncForce(e.target.checked)}
                />
