                className="flow-refresh"
                onClick={() => syncHost(true)}
                disabled={syncing || !syncForce}
              >
                {syncing ? 'Retrying…' : 'Retry with overwrite'}
              </button>
            </div>
          )}
        </div>
      )}
      {effective ? (
        <div className="flow-canvas">
          <ReactFlowProvider>
            <FlowCanvas
              nodes={nodes}
              edges={built.edges}
              onNodesChange={onNodesChange}
              onSelect={onSelect}
              onInspect={(sel) => {
                setInspect(sel)
                if (sel) setDraft(null)
              }}
              onSlotClick={(kind) => {
                setDraft(kind)
                setInspect(null)
                setSeeding(null)
              }}
              onSeed={(component) => {
                setSeeding(component)
                setDraft(null)
                setInspect(null)
              }}
              fitSignal={system ?? ''}
              theme={theme}
            />
          </ReactFlowProvider>
          {inspect && declared && (
            <FlowDetail
              selection={inspect}
              topology={declared}
              onClose={() => setInspect(null)}
