      } satisfies IntNodeData,
    })
  }

  // Vertical centering per topic: the average card-centre y of the
  // components wired to it, minus the topic's own half height. A topic's
  // place is between its publisher and subscribers, not on a row of its own.
  const topicY = new Map<string, number>()
  for (const [tid] of topicRefs) {
    const neighbours = comps
      .filter(
        (c) =>
          (c.publishes ?? []).some((p) => topicId(p.pubsub, p.topic) === tid) ||
          (c.subscribes ?? []).some((s) => topicId(s.pubsub, s.topic) === tid),
      )
      .map((c) => compPos.get(`component:${c.name}`))
      .filter((p): p is { x: number; y: number; col: number } => p !== undefined)
    if (neighbours.length === 0) continue
    const centre =
      neighbours.reduce((sum, p) => sum + p.y + NODE_H / 2, 0) / neighbours.length
    topicY.set(tid, centre - INFRA_H / 2)
  }

  for (const [tid, ref] of topicRefs) {
    const pos = place(depth.get(tid) ?? 0)
    const contracts = topicContracts(topo, ref.pubsub, ref.topic)
    const carried = topicMessages(topo, ref.pubsub, ref.topic)
    nodes.push({
      id: nodeId.get(tid)!,
      type: 'topic',
      parentId: groupId,
      extent: 'parent',
      // Topics are narrower than component cards; center them in the column.
      // Rows share them across the topic's neighbours, so centre vertically
      // on the average of the wired components rather than taking the row.
      position: { x: pos.x + (NODE_W - INFRA_W) / 2, y: topicY.get(tid) ?? pos.y },
      style: { width: INFRA_W, height: INFRA_H },
      data: {
        name: ref.topic,
        pubsub: ref.pubsub,
        contract: contracts.length > 1 ? `${carried.length} messages` : contracts[0],
        detail: carried.length > 0 ? carried.map((m) => `${m.name} · ${m.contract ?? '—'}`).join('\n') : undefined,
      } satisfies TopicNodeData,
    })
  }

  for (const g of ghosts) {
    const flow = g.dataFlow ?? (g.blockKind ? dataFlowFor(g.blockKind) : undefined)
    const pos = place(ghostCol(g))
    nodes.push({
      id: g.path,
      type: 'integration',
      parentId: groupId,
      extent: 'parent',
      position: { x: pos.x, y: pos.y },
      data: {
        name: g.name,
        template: g.blockKind || g.template,
        dataFlow: flow,
        selected: false,
        ghost: true,
      } satisfies IntNodeData,
    })
  }

  // The slot rail: one shared baseline below the deepest node, so the slots
  // align across columns instead of drifting with each column's stack. An
  // empty system has no node bottom — the rail is the content top.
  const nodeBottom = Math.max(
    0,
    ...colRows.map((rows) =>
      rows === 0
        ? 0
        : contentTop +
          ((maxRows - rows) * (NODE_H + ROW_GAP)) / 2 +
          (rows - 1) * (NODE_H + ROW_GAP) +
          NODE_H,
    ),
  )
  const slotY = nodeBottom === 0 ? contentTop : nodeBottom + ROW_GAP
  for (const s of slotDefs) {
    nodes.push({
      id: `slot:${s.kind}`,
      type: 'slot',
      parentId: groupId,
      extent: 'parent',
      position: { x: colX(s.col), y: slotY },
      style: { width: NODE_W, height: NODE_H },
      draggable: false,
      selectable: false,
      data: { kind: s.kind } satisfies SlotNodeData,
    })
  }

  const groupHeight = slotY + NODE_H + GROUP_PAD
  nodes.unshift({
    id: groupId,
    type: 'group',
    position: { x: 0, y: 0 },
    data: { title: topo.system, count: comps.length + ghosts.length } satisfies GroupNodeData,
    style: { width: groupWidth, height: groupHeight },
    draggable: false,
    selectable: false,
  })

  // Topic publish/subscribe edges. A publish leaves the component's right
  // ('ext') handle for the topic; a subscribe leaves the topic's right ('out')
  // handle for the subscriber.
  for (const c of comps) {
    const cref = `component:${c.name}`
    const comp = nodeId.get(cref)!
    for (const p of c.publishes ?? []) {
      const target = nodeId.get(topicId(p.pubsub, p.topic))
      if (!target) continue
      edges.push({
        id: `e:pub:${c.name}:${p.pubsub}/${p.topic}`,
        source: comp,
        sourceHandle: 'ext',
        target,
        targetHandle: 'in',
        markerEnd: { type: MarkerType.ArrowClosed },
        className: 'rf-edge-ext',
      })
    }
    for (const s of c.subscribes ?? []) {
      const source = nodeId.get(topicId(s.pubsub, s.topic))
      if (!source) continue
      edges.push({
        id: `e:sub:${s.pubsub}/${s.topic}:${c.name}`,
        type: 'subscription',
        source,
        sourceHandle: 'out',
        target: comp,
        targetHandle: 'in',
        markerEnd: { type: MarkerType.ArrowClosed },
        className: 'rf-edge-ext',
        data: { subscription: s } satisfies SubscriptionEdgeData,
      })
    }
  }

  // Externals sit outside the boundary: a source (input port) directly left
  // of its component, a destination (output port) on a rail off the
  // boundary's right edge, aligned with its component's row and bumped down
  // when rows collide. Sources flow in on the left, destinations out on the
  // right — the same in → process → out reading as the columns inside.
  const railX = groupWidth + EXT_GAP
  const railYs: number[] = []
  const railY = (want: number): number => {
    let y = want
    while (railYs.some((used) => Math.abs(used - y) < EXT_H + EXT_VGAP)) {
      y += EXT_H + EXT_VGAP
    }
    railYs.push(y)
    return y
  }
  const pushExternal = (id: string, data: ExtNodeData, x: number, y: number): void => {
    if (nodes.some((n) => n.id === id)) return
    nodes.push({
      id,
      type: 'external',
      position: { x, y },
      style: { width: EXT_W, height: EXT_H },
      data,
      draggable: true,
    })
  }

  for (const c of comps) {
    const cref = `component:${c.name}`
    const comp = nodeId.get(cref)!
    const anchor = compPos.get(cref)!
    for (const use of c.ports ?? []) {
      const port = portMeta.get(use.port)
      const isInput = use.direction === 'in'
      const extId = `ext:${use.port}`
      const data: ExtNodeData = {
        name: port?.externalSystem ? refName(port.externalSystem) : use.port,
        type: 'port',
        direction: isInput ? 'input' : undefined,
        port: use.port,
      }
      if (isInput) {
        pushExternal(extId, data, anchor.x - EXT_W - EXT_GAP, anchor.y)
        edges.push({
          id: `e:port:${c.name}:${use.port}`,
          source: extId,
          sourceHandle: 'out',
          target: comp,
          targetHandle: 'in',
          markerEnd: { type: MarkerType.ArrowClosed },
          className: 'rf-edge-ext',
        })
      } else {
        pushExternal(extId, data, railX, railY(anchor.y))
        edges.push({
          id: `e:port:${c.name}:${use.port}`,
          source: comp,
          sourceHandle: 'ext',
          target: extId,
          targetHandle: 'in',
          markerEnd: { type: MarkerType.ArrowClosed },
          className: 'rf-edge-ext',
        })
      }
    }
  }

  return { nodes, edges, ghosts }
}

function GroupNode({ data }: NodeProps) {
  const { title, count } = data as GroupNodeData
  return (
    <div className="rf-group">
      <div className="rf-group-title">
        <span>{title}</span>
        <span className="count">{count}</span>
      </div>
    </div>
  )
}

function IntegrationNode({ data }: NodeProps) {
  const { name, template, dataFlow, selected, trigger, ghost, seed } = data as IntNodeData
  const onSeed = useContext(SeedContext)
  const Icon = dataFlow ? DATA_FLOW_ICONS[dataFlow] : MemoryIcon
  return (
    <div className={`rf-int${selected ? ' selected' : ''}${ghost ? ' ghost' : ''}`}>
      <div className="rf-int-head">
        <Icon className="rf-int-icon" aria-hidden />
        <span className="rf-int-name">{name}</span>
        {template && <span className="rf-int-tag">{template}</span>}
        {trigger && (
          <span className="rf-int-tag" title="schedule trigger">
            {trigger}
          </span>
        )}
        {ghost && (
          <span
            className="rf-int-tag ghost-tag"
            title="scaffolded, not in the declared topology yet"
          >
            scaffolded
          </span>
        )}
        {/* The seed action sits last: the first tag's auto margin pushes the
            whole trailing cluster right, and the button hangs off its end. */}
        {seed === 'ready' && (
          <button
            type="button"
            className="rf-int-seed nodrag"
            title="Seed a test file into this extractor's dev folder"
            onClick={(e) => {
              // The card click selects the integration; the action is not a
              // selection.
              e.stopPropagation()
              onSeed(name)
            }}
          >
            <FileUploadIcon aria-hidden />
          </button>
        )}
        {seed === 'ghost' && (
          <button
            type="button"
            className="rf-int-seed"
            disabled
            title="Seeding needs the declared topology — update the host and refresh first"
          >
            <FileUploadIcon aria-hidden />
          </button>
        )}
      </div>

      <Handle type="target" position={Position.Left} id="in" />
      <Handle type="source" position={Position.Bottom} id="infra" />
      <Handle type="source" position={Position.Right} id="ext" />
    </div>
  )
}

// SlotNode is a create placeholder: one per block-kind column, low-contrast
// until hovered. Clicking it opens the create drawer for that kind. It has no
// handles — a slot carries no wiring.
const SLOT_LABELS: Record<SlotKind, string> = {
  extractor: 'Extractor',
  transactional: 'Core block',
  loader: 'Loader',
}

function SlotNode({ data }: NodeProps) {
  const { kind } = data as SlotNodeData
  return (
    <div className="rf-slot">
      <span className="rf-slot-plus" aria-hidden>
        +
      </span>
      <div className="rf-slot-text">
        <span className="rf-slot-name">{SLOT_LABELS[kind]}</span>
        <span className="rf-slot-hint">scaffold a new block</span>
      </div>
    </div>
  )
}

// TopicNode is a declared pub/sub topic: the first-class hop between
// components a declared topology makes visible. Contract topics show their
// contract ref; internal ones their data entity. The node draws as a
// horizontal cylinder — the message-channel glyph — so a topic reads as
// infrastructure between components, never as another component card.
function TopicNode({ data }: NodeProps) {
  const { name, entity, contract, detail } = data as TopicNodeData
  // Topic names share a long common prefix, so lead with the short entity and
  // keep the full topic/contract in a tooltip. Fall back to the name when a
  // topic declares no entity.
  const primary = entity ?? name
  const secondary = contract ?? name
  const tip = [name, detail ?? contract].filter(Boolean).join('\n')
  return (
    <div className="rf-infra pubsub rf-topic-cyl" title={tip}>
      {/* Silhouette: a rectangle with both ends bulging as elliptical arcs;
          the extra arc is the near cap's seam, making the left end read as
          the visible face of the cylinder. */}
      <svg className="rf-cyl" viewBox="0 0 200 76" aria-hidden focusable="false">
        <path className="rf-cyl-body" d="M 12 3 H 188 A 9 35 0 0 1 188 73 H 12 A 9 35 0 0 1 12 3 Z" />
        <path className="rf-cyl-seam" d="M 12 3 A 9 35 0 0 1 12 73" />
      </svg>
      <Handle type="target" position={Position.Left} id="in" />
      <HubIcon className="rf-infra-icon" aria-hidden />
      <div className="rf-infra-text">
        <span className="rf-infra-name">{primary}</span>
        <span className="rf-infra-kind">{secondary}</span>
      </div>
      <Handle type="source" position={Position.Right} id="out" />
    </div>
  )
}

function ExternalNode({ data }: NodeProps) {
  const { name, type, direction } = data as ExtNodeData
  const isDisk = /localstorage|localfile|disk|file/i.test(type)
  const Icon = isDisk ? HardDriveIcon : CloudIcon
  const kind = direction === 'input' ? 'source' : isDisk ? 'disk' : 'external'
  return (
    <div className="rf-ext">
      <Handle type="target" position={Position.Left} id="in" />
      <Handle type="target" position={Position.Top} id="top" />
      <Handle type="source" position={Position.Right} id="out" />
      <Icon className="rf-ext-icon" aria-hidden />
      <div className="rf-ext-text">
        <span className="rf-ext-name">{name}</span>
        <span className="rf-ext-kind" title={type}>
          {kind}
        </span>
      </div>
    </div>
  )
}

const NODE_TYPES = {
  group: GroupNode,
  integration: IntegrationNode,
  external: ExternalNode,
  topic: TopicNode,
  slot: SlotNode,
}

const EDGE_TYPES = {
  subscription: SubscriptionEdge,
}

package dashboard

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/huandu/xstrings"

	"github.com/integrio-intropy/intropy-cli/internal/system"
	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// syncSystemRequest is the optional POST /api/systems/{path} body.
type syncSystemRequest struct {
	// Force lets an update overwrite diverged declaration files (sys
	// update --force) or a create render into a non-empty host directory.
	Force bool `json:"force,omitempty"`
}

// syncSystemResponse reports what a host sync did. Action says which verb
// ran: "update" folded orphans into an existing host, "create" assembled a
// new one, "none" found an up-to-date host and wrote nothing.
type syncSystemResponse struct {
	Action      string   `json:"action"`
	HostDir     string   `json:"hostDir,omitempty"`
	System      string   `json:"system,omitempty"`
	Added       []string `json:"added,omitempty"`
	Kept        []string `json:"kept,omitempty"`
	Diagnostics []string `json:"diagnostics,omitempty"`
}

// syncSystem is POST /api/systems/{path...}: re-assemble one system's host
// the way the CLI would — `sys update` when the directory already has a
// host, `sys create` when it does not. The path is the system directory,
// never the workspace root of a multi-system workspace: sys update's
// single-host contract holds per system.
func (s *apiServer) syncSystem(w http.ResponseWriter, r *http.Request) {
	dir, err := s.resolveSystemDir(r.PathValue("path"))
	if err != nil {
		writeError(w, http.StatusUnprocessableEntity, err.Error())
		return
	}

	var req syncSystemRequest
	dec := json.NewDecoder(io.LimitReader(r.Body, maxCreateBodyBytes))
	if err := dec.Decode(&req); err != nil && !errors.Is(err, io.EOF) {
		writeError(w, http.StatusBadRequest, "invalid request body: "+err.Error())
		return
	}

	// The same serialization bargain template creates make: two concurrent
	// syncs of one host would race on its files, and each run may clone the
	// template library.
	s.createMu.Lock()
	defer s.createMu.Unlock()

	// The host renders from the release the dashboard holds, so assembling a
	// system and scaffolding into it can never pin different ones.
	tag, err := s.libraryTag(r.Context())
	if err != nil {
		writeError(w, http.StatusBadGateway, err.Error())
		return
	}

	hosts, _ := template.ListSystemHosts(dir)
	if len(hosts) == 0 {
		s.createHost(w, r, dir, tag, req.Force)
		return
	}
	s.updateHost(w, r, dir, tag, req.Force)
}

// updateHost runs `sys update` against the system directory: fold every
// scaffolded-but-undeclared component into the existing host. No orphans is
// a successful no-op (action "none"), matching the command's own contract.
func (s *apiServer) updateHost(w http.ResponseWriter, r *http.Request, dir, tag string, force bool) {
	var out, logs bytes.Buffer
	err := system.Update(r.Context(), system.UpdateOptions{
		StartDir:   dir,
		Force:      force,
		Version:    tag,
		OutputJSON: "-",
		Stdout:     &out,
		Stderr:     &logs,
		UserAgent:  s.templates.userAgent,
		Owner:      s.templates.owner,
		Repo:       s.templates.repo,
		Source:     s.templates.source,
	})
	if err != nil {
		writeError(w, syncErrorStatus(err), err.Error())
		return
	}

	resp := syncSystemResponse{Action: "none", Diagnostics: diagnosticLines(logs.String())}
	// The result document is only written when the update added something;
	// an empty stdout is the no-orphans path.
	var res system.UpdateResult
	if out.Len() > 0 && json.Unmarshal(out.Bytes(), &res) == nil {
		resp.Action = "update"
		resp.HostDir = s.relPath(res.HostDir)
		resp.System = res.System
		resp.Added = res.Added
		resp.Kept = res.Kept
	}
	writeJSON(w, http.StatusOK, resp)
}

// createHost runs `sys create` for a system directory that has no host yet:
// the system is named after its directory (the same rule that labels the
// workspace pseudo-system) and the host renders inside it as <name>-host,
// a sibling of the components and the contracts project.
func (s *apiServer) createHost(w http.ResponseWriter, r *http.Request, dir, tag string, force bool) {
	name := hostSystemName(dir)
	var out, logs bytes.Buffer
	err := system.Create(r.Context(), system.CreateOptions{
		Name:       name,
		StartDir:   dir,
		OutputDir:  filepath.Join(dir, xstrings.ToKebabCase(name)+"-host"),
		Version:    tag,
		Force:      force,
		OutputJSON: "-",
		Stdout:     &out,
		Stderr:     &logs,
		UserAgent:  s.templates.userAgent,
		Owner:      s.templates.owner,
		Repo:       s.templates.repo,
		Source:     s.templates.source,
	})
	if err != nil {
		writeError(w, syncErrorStatus(err), err.Error())
		return
	}

	resp := syncSystemResponse{Action: "create", Diagnostics: diagnosticLines(logs.String())}
	var res system.CreateResult
	if out.Len() > 0 && json.Unmarshal(out.Bytes(), &res) == nil {
		resp.HostDir = s.relPath(res.OutputDir)
		resp.System = res.System.Name
		for _, c := range res.System.Components {
			resp.Added = append(resp.Added, c.AppID)
		}
	}
	writeJSON(w, http.StatusOK, resp)
}

// resolveSystemDir confines a root-relative system path to the workspace,
// under the same segment rules a create request's dir obeys; "" and "."
// mean the workspace root itself. The directory must exist — the endpoint
// syncs systems, it does not invent them.
func (s *apiServer) resolveSystemDir(rel string) (string, error) {
	segments, err := splitCreateDir(rel)
	if err != nil {
		return "", err
	}
	dir := filepath.Join(append([]string{s.root}, segments...)...)
	if info, statErr := os.Stat(dir); statErr != nil || !info.IsDir() {
		return "", fmt.Errorf("directory %q does not exist under the workspace root", rel)
	}
	return dir, nil
}

// hostSystemName names a system created for dir after the directory itself,
// resolved to absolute first so the workspace root ("." from a relative
// invocation) still yields its folder name.
func hostSystemName(dir string) string {
	if abs, err := filepath.Abs(dir); err == nil {
		dir = abs
	}
	return filepath.Base(dir)
}

// syncErrorStatus maps a host sync failure onto the status the banner acts
// on: a divergence the command refuses to overwrite is a 409 (the retry
// offers force), a workspace-shape problem is a 422, and an upstream
// template fetch failure is a 502.
func syncErrorStatus(err error) int {
	msg := err.Error()
	switch {
	case strings.Contains(msg, "--force"), strings.Contains(msg, "not empty"):
		return http.StatusConflict
	case strings.Contains(msg, "fetch"), strings.Contains(msg, "download"):
		return http.StatusBadGateway
	case strings.Contains(msg, "system host"),
		strings.Contains(msg, "not a workspace"),
		strings.Contains(msg, "scaffold"),
		strings.Contains(msg, "component"):
		return http.StatusUnprocessableEntity
	}
	return http.StatusInternalServerError
}
