package dashboard

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"time"

	"github.com/huandu/xstrings"
	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// The assistant turns a prose request ("partners send orders over SFTP; set
// up the intake") into the `intropy` commands that would build it. The LLM
// only proposes; every step is then resolved through template.PrepareCreate —
// the same value resolution `int create --no-input` runs — so a plan the
// dashboard shows is a plan the CLI would accept. Nothing is written until
// the client applies the steps through the ordinary create and sync
// endpoints, one at a time.

// DefaultAssistantURL is Berget AI's OpenAI-compatible API base.
const DefaultAssistantURL = "https://api.berget.ai/v1"

// DefaultAssistantModel is a Berget model that honours json_schema output.
const DefaultAssistantModel = "mistralai/Mistral-Small-3.2-24B-Instruct-2506"

// assistantTimeout bounds one completion. Planning is a single short JSON
// answer; a model that has not produced it in two minutes is not going to.
const assistantTimeout = 2 * time.Minute

// maxPromptBytes caps the user's request. A paragraph is the expected size.
const maxPromptBytes = 8 * 1024

// assistantRepairs is how many times a plan that fails validation is sent
// back to the model with the errors. One round fixes the usual slips (a
// kebab-case name, a missing required value); more rarely helps.
const assistantRepairs = 1

// AssistantConfig selects the LLM endpoint the flow view's assistant plans
// with. An empty APIKey disables the assistant; the rest of the dashboard
// is unaffected.
type AssistantConfig struct {
	BaseURL string
	APIKey  string
	Model   string
}

// chatMessage is one OpenAI-style chat message.
type chatMessage struct {
	Role    string `json:"role"`
	Content string `json:"content"`
}

// chatFunc completes a conversation into a JSON document matching schema.
// Production posts to Berget; tests substitute a canned answer.
type chatFunc func(ctx context.Context, messages []chatMessage, schema json.RawMessage) (string, error)

// assistantProvider is the configured planner. A nil provider means the
// dashboard was started without an API key.
type assistantProvider struct {
	model string
	chat  chatFunc
}

// newAssistantProvider returns nil when cfg carries no API key.
func newAssistantProvider(cfg AssistantConfig) *assistantProvider {
	if cfg.APIKey == "" {
		return nil
	}
	if cfg.BaseURL == "" {
		cfg.BaseURL = DefaultAssistantURL
	}
	if cfg.Model == "" {
		cfg.Model = DefaultAssistantModel
	}
	client := &http.Client{Timeout: assistantTimeout}
	return &assistantProvider{model: cfg.Model, chat: openAIChat(client, cfg)}
}

// openAIChat posts to an OpenAI-compatible /chat/completions endpoint with a
// strict json_schema response format.
func openAIChat(client *http.Client, cfg AssistantConfig) chatFunc {
	endpoint := strings.TrimRight(cfg.BaseURL, "/") + "/chat/completions"
	return func(ctx context.Context, messages []chatMessage, schema json.RawMessage) (string, error) {
		body, err := json.Marshal(map[string]any{
			"model":       cfg.Model,
			"messages":    messages,
			"temperature": 0.2,
			"response_format": map[string]any{
				"type": "json_schema",
				"json_schema": map[string]any{
					"name":   "intropy_plan",
					"strict": true,
					"schema": schema,
				},
			},
		})
		if err != nil {
			return "", err
		}
		req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(body))
		if err != nil {
			return "", err
		}
		req.Header.Set("Authorization", "Bearer "+cfg.APIKey)
		req.Header.Set("Content-Type", "application/json")
		resp, err := client.Do(req)
		if err != nil {
			return "", fmt.Errorf("berget: %w", err)
		}
		defer resp.Body.Close()
		raw, err := io.ReadAll(io.LimitReader(resp.Body, 4<<20))
		if err != nil {
			return "", fmt.Errorf("berget: read response: %w", err)
		}
		if resp.StatusCode != http.StatusOK {
			return "", fmt.Errorf("berget: %s: %s", resp.Status, strings.TrimSpace(string(raw)))
		}
		var out struct {
			Choices []struct {
				Message struct {
					Content string `json:"content"`
				} `json:"message"`
			} `json:"choices"`
		}
		if err := json.Unmarshal(raw, &out); err != nil {
			return "", fmt.Errorf("berget: decode response: %w", err)
		}
		if len(out.Choices) == 0 {
			return "", errors.New("berget: response has no choices")
		}
		return out.Choices[0].Message.Content, nil
	}
}

// planSchema is the JSON the model must answer with. Every property is
// required because strict json_schema mode demands it: an unused message
// flag is "", not absent. Values travel as key/value strings, exactly as
// --set would carry them, so ParseSets applies the CLI's own coercion.
var planSchema = json.RawMessage(`{
  "type": "object",
  "properties": {
    "summary": {"type": "string"},
    "steps": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "template": {"type": "string"},
          "name": {"type": "string"},
          "publishes": {"type": "string"},
          "subscribe": {"type": "string"},
          "set": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "key": {"type": "string"},
                "value": {"type": "string"}
              },
              "required": ["key", "value"],
              "additionalProperties": false
            }
          },
          "why": {"type": "string"}
        },
        "required": ["template", "name", "publishes", "subscribe", "set", "why"],
        "additionalProperties": false
      }
    }
  },
  "required": ["summary", "steps"],
  "additionalProperties": false
}`)

// llmPlan is the model's answer, decoded from planSchema.
type llmPlan struct {
	Summary string    `json:"summary"`
	Steps   []llmStep `json:"steps"`
}

type llmStep struct {
	Template  string `json:"template"`
	Name      string `json:"name"`
	Publishes string `json:"publishes"`
	Subscribe string `json:"subscribe"`
	Set       []struct {
		Key   string `json:"key"`
		Value string `json:"value"`
	} `json:"set"`
	Why string `json:"why"`
}

// planRequest is the POST /api/assistant/plan body.
type planRequest struct {
	Prompt string `json:"prompt"`
	// System is the root-relative system directory the plan targets; "" or
	// "." is the workspace root.
	System string `json:"system"`
}

// planStep is one command of a validated plan. Kind "int-create" carries
// the create request the client posts to /api/templates/{template}/create;
// kind "sys-sync" is the POST /api/systems/{system} that assembles the host.
type planStep struct {
	ID      string `json:"id"`
	Kind    string `json:"kind"`
	Command string `json:"command"`
	Why     string `json:"why,omitempty"`
	// Error is why the step cannot run as planned. A plan with any step in
	// error is shown but not applied.
	Error string `json:"error,omitempty"`

	Template  string         `json:"template,omitempty"`
	BlockKind string         `json:"blockKind,omitempty"`
	Request   *createRequest `json:"request,omitempty"`
	// OutputDir is the root-relative directory the step renders into.
	OutputDir string `json:"outputDir,omitempty"`
	// Values are the resolved render values the scaffold record will carry,
	// reserved keys removed — what the step would write, before it runs.
	Values map[string]any `json:"values,omitempty"`
	// Preview is the component the step adds to the system topology, in the
	// topology.intropy.io/v1 shape the canvas already draws.
	Preview *previewComponent `json:"preview,omitempty"`

	// System is the sys-sync step's target directory.
	System string `json:"system,omitempty"`
}

// previewComponent mirrors the topology record's component wiring for a
// component that does not exist yet.
type previewComponent struct {
	Name       string           `json:"name"`
	Kind       string           `json:"kind"`
	Publishes  []previewPublish `json:"publishes,omitempty"`
	Subscribes []previewSub     `json:"subscribes,omitempty"`
}

type previewPublish struct {
	Pubsub  string `json:"pubsub"`
	Topic   string `json:"topic"`
	Message string `json:"message"`
}

type previewSub struct {
	Pubsub string         `json:"pubsub"`
	Topic  string         `json:"topic"`
	Routes []previewRoute `json:"routes"`
}

type previewRoute struct {
	Message string `json:"message"`
}

// planResponse is the POST /api/assistant/plan payload.
type planResponse struct {
	Summary string     `json:"summary"`
	Steps   []planStep `json:"steps"`
	Model   string     `json:"model"`
	Version string     `json:"version"`
}

// systemPubsub is the pub/sub component every system declares; the
// system-host template names it independently of the system.
const systemPubsub = "pubsub"

// assistantStatus is GET /api/assistant: whether planning is available.
func (s *apiServer) assistantStatus(w http.ResponseWriter, _ *http.Request) {
	if s.assistant == nil {
		writeJSON(w, http.StatusOK, map[string]any{"enabled": false})
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"enabled": true, "model": s.assistant.model})
}

// planAssistant is POST /api/assistant/plan: ask the model for a plan,
// validate every step against the template library, give the model one
// chance to repair what failed, and return the commands. It writes nothing.
func (s *apiServer) planAssistant(w http.ResponseWriter, r *http.Request) {
	if s.assistant == nil {
		writeError(w, http.StatusServiceUnavailable, "assistant is not configured\nset BERGET_API_KEY and restart 'intropy dashboard'")
		return
	}
	var req planRequest
	if err := json.NewDecoder(io.LimitReader(r.Body, maxPromptBytes*2)).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body: "+err.Error())
		return
	}
	req.Prompt = strings.TrimSpace(req.Prompt)
	if req.Prompt == "" {
		writeError(w, http.StatusBadRequest, "prompt is required")
		return
	}
	if len(req.Prompt) > maxPromptBytes {
		writeError(w, http.StatusBadRequest, fmt.Sprintf("prompt exceeds %d bytes", maxPromptBytes))
		return
	}
	sysRel := req.System
	if sysRel == "" {
		sysRel = "."
	}
	sysDir, err := s.resolveSystemDir(sysRel)
	if err != nil {
		writeError(w, http.StatusUnprocessableEntity, err.Error())
		return
	}

	lib, err := s.fetchLibrary(r.Context())
	if err != nil {
		writeError(w, http.StatusBadGateway, err.Error())
		return
	}
	catalog := componentCatalog(lib)
	tag := lib.Version
	lib.Close()
	if len(catalog) == 0 {
		writeError(w, http.StatusBadGateway, fmt.Sprintf("template library %s has no component templates", tag))
		return
	}

	existing := s.systemBlocks(sysRel)
	messages := []chatMessage{
		{Role: "system", Content: assistantSystemPrompt(catalog, existing, s.organization)},
		{Role: "user", Content: req.Prompt},
	}

	var (
		plan  llmPlan
		steps []planStep
	)
	for attempt := 0; ; attempt++ {
		answer, err := s.assistant.chat(r.Context(), messages, planSchema)
		if err != nil {
			writeError(w, http.StatusBadGateway, err.Error())
			return
		}
		plan, err = decodePlan(answer)
		if err != nil {
			writeError(w, http.StatusBadGateway, err.Error())
			return
		}
		steps = s.validatePlan(r.Context(), plan, catalog, sysRel, sysDir, tag)
		failed := planErrors(steps)
		if len(failed) == 0 || attempt >= assistantRepairs {
			break
		}
		messages = append(messages,
			chatMessage{Role: "assistant", Content: answer},
			chatMessage{Role: "user", Content: "These steps fail validation; answer with a corrected full plan:\n" + strings.Join(failed, "\n")},
		)
	}

	if len(steps) > 0 {
		steps = append(steps, s.hostStep(sysRel, sysDir, len(steps)+1))
	}
	writeJSON(w, http.StatusOK, planResponse{
		Summary: strings.TrimSpace(plan.Summary),
		Steps:   steps,
		Model:   s.assistant.model,
		Version: tag,
	})
}

// decodePlan parses the model's answer. Some models wrap JSON in a Markdown
// fence even under json_schema; the fence is stripped rather than failing.
func decodePlan(answer string) (llmPlan, error) {
	answer = strings.TrimSpace(answer)
	if strings.HasPrefix(answer, "```") {
		answer = strings.TrimPrefix(answer, "```json")
		answer = strings.TrimPrefix(answer, "```")
		answer = strings.TrimSuffix(strings.TrimSpace(answer), "```")
	}
	var plan llmPlan
	if err := json.Unmarshal([]byte(answer), &plan); err != nil {
		return llmPlan{}, fmt.Errorf("assistant answer is not a plan: %w", err)
	}
	return plan, nil
}

// planErrors lists each failed step as "<command>: <error>" for the repair
// prompt.
func planErrors(steps []planStep) []string {
	var out []string
	for _, st := range steps {
		if st.Error != "" {
			out = append(out, fmt.Sprintf("- %s: %s", st.Command, st.Error))
		}
	}
	return out
}

// catalogTemplate is one component template as the model sees it.
type catalogTemplate struct {
	Name        string         `json:"template"`
	Description string         `json:"description,omitempty"`
	BlockKind   string         `json:"blockKind"`
	MessageFlag string         `json:"messageFlag,omitempty"`
	Parameters  []catalogParam `json:"parameters"`

	fields map[string]template.FieldSpec
}

type catalogParam struct {
	Name        string `json:"name"`
	Type        string `json:"type"`
	Required    bool   `json:"required,omitempty"`
	Default     any    `json:"default,omitempty"`
	Enum        []any  `json:"enum,omitempty"`
	Description string `json:"description,omitempty"`
}

// componentCatalog describes the library's component templates — those
// carrying a block-kind label. Hosts, contracts and examples are not
// something a plan scaffolds directly: the host is the plan's last step,
// and the contracts project comes with it.
func componentCatalog(lib *template.Library) map[string]catalogTemplate {
	names, err := lib.List()
	if err != nil {
		return nil
	}
	out := map[string]catalogTemplate{}
	for _, name := range names {
		desc, err := lib.Describe(name)
		if err != nil {
			continue
		}
		kind := desc.Labels[template.TemplateBlockKindLabel]
		if kind == "" {
			continue
		}
		msgParams := messageParametersFromLabels(desc.Labels)
		ct := catalogTemplate{
			Name:        name,
			Description: desc.Description,
			BlockKind:   kind,
			fields:      map[string]template.FieldSpec{},
		}
		switch template.MessageDirection(kind) {
		case template.MessageDirectionPublish:
			ct.MessageFlag = "publishes"
		case template.MessageDirectionSubscribe:
			ct.MessageFlag = "subscribe"
		}
		for _, f := range desc.Fields {
			ct.fields[f.Name] = f
			// name rides on -n and the message parameters on their flag;
			// listing them as --set keys invites the conflicts the CLI refuses.
			if f.Name == template.KeyName || contains(msgParams, f.Name) {
				continue
			}
			ct.Parameters = append(ct.Parameters, catalogParam{
				Name:        f.Name,
				Type:        f.Type,
				Required:    f.Required,
				Default:     f.Default,
				Enum:        f.Enum,
				Description: truncate(f.Description, 240),
			})
		}
		out[name] = ct
	}
	return out
}

// existingBlock is one component already scaffolded in the target system.
type existingBlock struct {
	Dir       string `json:"dir"`
	Template  string `json:"template"`
	BlockKind string `json:"blockKind,omitempty"`
	Publishes string `json:"publishes,omitempty"`
	Subscribe string `json:"subscribes,omitempty"`
	Topic     string `json:"topic,omitempty"`
}

// systemBlocks lists the component scaffolds whose system is sysRel, so the
// model can reuse their messages instead of inventing parallel ones.
func (s *apiServer) systemBlocks(sysRel string) []existingBlock {
	entries, systems := s.scan()
	var out []existingBlock
	for _, e := range entries {
		sum := s.summarize(e, systems)
		sp := sum.SystemPath
		if sp == "" {
			sp = "."
		}
		if sp != sysRel {
			continue
		}
		b := existingBlock{Dir: sum.Name, Template: e.Template, BlockKind: e.BlockKind}
		b.Publishes, _ = template.SoftValue(e.Values, template.KeyPublishes)
		b.Subscribe, _ = template.SoftValue(e.Values, template.KeySubscribes)
		b.Topic, _ = template.SoftValue(e.Values, "topic")
		out = append(out, b)
	}
	return out
}

// assistantSystemPrompt grounds the model in the library release and the
// workspace. The rules restate what validation enforces, so a first answer
// usually passes without a repair round.
func assistantSystemPrompt(catalog map[string]catalogTemplate, existing []existingBlock, org string) string {
	names := make([]string, 0, len(catalog))
	for n := range catalog {
		names = append(names, n)
	}
	sort.Strings(names)
	list := make([]catalogTemplate, 0, len(names))
	for _, n := range names {
		list = append(list, catalog[n])
	}
	cat, _ := json.MarshalIndent(list, "", "  ")
	ws, _ := json.MarshalIndent(existing, "", "  ")
	if len(existing) == 0 {
		ws = []byte("[] (empty system)")
	}
	orgLine := "No organization is configured: set the organization parameter on every step, PascalCase, derived from the request or 'Acme' if nothing suggests one."
	if org != "" {
		orgLine = fmt.Sprintf("The configured organization is %q; the dashboard sets it, so omit it from set.", org)
	}

	return `You plan Intropy integration systems. You turn a request into calls of
` + "`intropy int create <template> -n <Name> [--publishes <Message> | --subscribe <Message>] [--set key=value ...]`" + `.

Model:
- An extractor brings data in from an external source and publishes exactly one message onto a topic.
- A loader subscribes to exactly one message from a topic and delivers it to an external destination.
- A transactional integration moves data point to point with no messages.
- Components meet only through messages on topics. The topic defaults to the message name; set the
  topic parameter only when several messages or producers must share one topic.
- The system host is assembled after the components by the dashboard. Never plan it.

Rules:
- Use only these templates and only their listed parameters. Never invent parameters (there is no
  port, contract, or transport parameter: protocols such as SFTP or HTTP are separate extractors,
  named after the source).
- name: PascalCase, unique, descriptive (e.g. SftpOrderIntake). It becomes the directory in kebab-case.
- An extractor sets publishes and leaves subscribe "". A loader sets subscribe and leaves publishes "".
  A transactional template leaves both "".
- Message names are PascalCase nouns (e.g. PartnerOrder). Reuse messages already in the system.
- set holds only parameters that differ from their default or are required with no default.
- ` + orgLine + `
- Prefer the smallest plan that satisfies the request. Do not add loaders unless the request implies delivery.
- summary: one sentence starting with "Plan:" describing the components and how they connect.
- why: one short clause per step.

Templates:
` + string(cat) + `

Components already in this system:
` + string(ws)
}

// validatePlan resolves every model step through PrepareCreate — the
// non-interactive value resolution `int create --no-input` runs — and
// renders the equivalent command. Steps keep their order; an invalid one
// carries its error instead of a request.
func (s *apiServer) validatePlan(ctx context.Context, plan llmPlan, catalog map[string]catalogTemplate, sysRel, sysDir, tag string) []planStep {
	taken := map[string]bool{}
	if ents, err := os.ReadDir(sysDir); err == nil {
		for _, e := range ents {
			taken[e.Name()] = true
		}
	}
	steps := make([]planStep, 0, len(plan.Steps))
	for i, ls := range plan.Steps {
		st := s.validateStep(ctx, ls, catalog, sysRel, tag, taken)
		st.ID = fmt.Sprintf("step-%d", i+1)
		steps = append(steps, st)
	}
	return steps
}

func (s *apiServer) validateStep(ctx context.Context, ls llmStep, catalog map[string]catalogTemplate, sysRel, tag string, taken map[string]bool) planStep {
	ls.Name = strings.TrimSpace(ls.Name)
	ls.Publishes = strings.TrimSpace(ls.Publishes)
	ls.Subscribe = strings.TrimSpace(ls.Subscribe)
	st := planStep{Kind: "int-create", Template: ls.Template, Why: strings.TrimSpace(ls.Why)}

	// The set pairs keep the model's order for the command line; the map is
	// what ParseSets makes of them, exactly as --set would.
	var pairs []string
	for _, kv := range ls.Set {
		key := strings.TrimSpace(kv.Key)
		if key == "" {
			continue
		}
		pairs = append(pairs, key+"="+kv.Value)
	}
	ct, known := catalog[ls.Template]
	if known && s.organization != "" {
		if _, declared := ct.fields["organization"]; declared && !hasSetKey(pairs, "organization") {
			pairs = append(pairs, "organization="+s.organization)
		}
	}
	st.Command = intCreateCommand(sysRel, ls, pairs, tag)

	fail := func(format string, a ...any) planStep {
		st.Error = fmt.Sprintf(format, a...)
		return st
	}
	if !known {
		return fail("unknown template %q", ls.Template)
	}
	st.BlockKind = ct.BlockKind
	if ls.Name == "" {
		return fail("name is required")
	}
	if ls.Publishes != "" && ls.Subscribe != "" {
		return fail("cannot combine --subscribe with --publishes (one component is one direction)")
	}
	for _, p := range pairs {
		key, _, _ := strings.Cut(p, "=")
		if isReservedValueKey(key) {
			return fail("value %q is reserved and cannot be supplied", key)
		}
		if key == template.KeyName {
			return fail("cannot combine --name with --set name= (they conflict)")
		}
		if _, ok := ct.fields[key]; !ok {
			return fail("unknown parameter %q for template %s", key, ct.Name)
		}
	}
	sets, err := template.ParseSets(pairs)
	if err != nil {
		return fail("%v", err)
	}

	leaf := xstrings.ToKebabCase(ls.Name)
	if taken[leaf] {
		return fail("directory %s already exists in this system", leaf)
	}

	resolveSets := make(map[string]any, len(sets)+1)
	for k, v := range sets {
		resolveSets[k] = v
	}
	resolveSets[template.KeyName] = ls.Name
	prep, err := template.PrepareCreate(ctx, template.CreateOptions{
		Template:         ls.Template,
		Version:          tag,
		SetValues:        resolveSets,
		NoInput:          true,
		Stdin:            strings.NewReader(""),
		Stdout:           io.Discard,
		Stderr:           io.Discard,
		UserAgent:        s.templates.userAgent,
		Owner:            s.templates.owner,
		Repo:             s.templates.repo,
		Source:           s.templates.source,
		SubscribeMessage: ls.Subscribe,
		PublishesMessage: ls.Publishes,
	})
	if err != nil {
		return fail("%v", err)
	}
	defer prep.Cleanup()

	taken[leaf] = true
	st.OutputDir = joinRel(sysRel, leaf)
	st.Values = map[string]any{}
	for k, v := range prep.Values {
		if !isReservedValueKey(k) {
			st.Values[k] = v
		}
	}
	st.Request = &createRequest{
		Name:      ls.Name,
		Dir:       sysRel,
		Values:    sets,
		Subscribe: ls.Subscribe,
		Publishes: ls.Publishes,
	}
	st.Preview = previewFor(leaf, ct.BlockKind, ls, prep.Values)
	return st
}

// previewFor derives the topology wiring the scaffold record implies: the
// topic is the resolved topic value, else the message name — the default
// both producing and consuming templates declare.
func previewFor(appID, kind string, ls llmStep, values map[string]any) *previewComponent {
	c := &previewComponent{Name: appID, Kind: kind}
	topic, _ := values["topic"].(string)
	switch {
	case ls.Publishes != "":
		if topic == "" {
			topic = ls.Publishes
		}
		c.Publishes = []previewPublish{{Pubsub: systemPubsub, Topic: topic, Message: ls.Publishes}}
	case ls.Subscribe != "":
		if topic == "" {
			topic = ls.Subscribe
		}
		c.Subscribes = []previewSub{{Pubsub: systemPubsub, Topic: topic, Routes: []previewRoute{{Message: ls.Subscribe}}}}
	}
	return c
}

// hostStep is the plan's last step: assemble the host the way the flow
// view's banner does — sys update when the system has one, sys create
// otherwise, named after the directory.
func (s *apiServer) hostStep(sysRel, sysDir string, n int) planStep {
	st := planStep{
		ID:     fmt.Sprintf("step-%d", n),
		Kind:   "sys-sync",
		System: sysRel,
	}
	if hosts, _ := template.ListSystemHosts(sysDir); len(hosts) > 0 {
		st.Command = cliPrefix(sysRel) + "sys update"
		st.Why = "fold the new components into the existing system host"
		return st
	}
	name := hostSystemName(sysDir)
	st.Command = cliPrefix(sysRel) + fmt.Sprintf("sys create -n %s -o %s", shellQuote(name), shellQuote(xstrings.ToKebabCase(name)+"-host"))
	st.Why = "assemble the system host from the scaffolded components"
	return st
}

// intCreateCommand renders the CLI call a step stands for. The template
// version is pinned because the dashboard renders from one release; without
// it the command could resolve a newer one than the plan was checked against.
func intCreateCommand(sysRel string, ls llmStep, pairs []string, tag string) string {
	var b strings.Builder
	b.WriteString(cliPrefix(sysRel))
	b.WriteString("int create ")
	b.WriteString(shellQuote(ls.Template))
	b.WriteString(" -n ")
	b.WriteString(shellQuote(ls.Name))
	if ls.Publishes != "" {
		b.WriteString(" --publishes " + shellQuote(ls.Publishes))
	}
	if ls.Subscribe != "" {
		b.WriteString(" --subscribe " + shellQuote(ls.Subscribe))
	}
	for _, p := range pairs {
		b.WriteString(" --set " + shellQuote(p))
	}
	if tag != "" {
		b.WriteString(" --template-version " + shellQuote(tag))
	}
	b.WriteString(" --no-input")
	return b.String()
}

// cliPrefix is "intropy " plus -C for a system below the workspace root.
func cliPrefix(sysRel string) string {
	if sysRel == "" || sysRel == "." {
		return "intropy "
	}
	return "intropy -C " + shellQuote(sysRel) + " "
}

var shellSafe = regexp.MustCompile(`^[A-Za-z0-9_./:=@,+-]+$`)

// shellQuote single-quotes s unless every character is shell-inert.
func shellQuote(s string) string {
	if s != "" && shellSafe.MatchString(s) {
		return s
	}
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}

func joinRel(base, leaf string) string {
	if base == "" || base == "." {
		return leaf
	}
	return filepath.ToSlash(filepath.Join(base, leaf))
}

func hasSetKey(pairs []string, key string) bool {
	for _, p := range pairs {
		if k, _, _ := strings.Cut(p, "="); k == key {
			return true
		}
	}
	return false
}

func contains(list []string, s string) bool {
	for _, v := range list {
		if v == s {
			return true
		}
	}
	return false
}

func truncate(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n] + "…"
}

