package dashboard

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/template/templatetest"
)

const assistantExtractorYAML = `apiVersion: intropy.io/v1
kind: Template
metadata:
  name: extractor
  labels:
    intropy.io/block-kind: extractor
    intropy.io/message-params: publishes
spec:
  parameters:
    type: object
    required: [name, organization, publishes]
    properties:
      name:
        type: string
        pattern: '^[A-Z][A-Za-z0-9]*$'
      organization:
        type: string
      publishes:
        type: string
      topic:
        type: string
`

const assistantLoaderYAML = `apiVersion: intropy.io/v1
kind: Template
metadata:
  name: loader
  labels:
    intropy.io/block-kind: loader
    intropy.io/message-params: routes
spec:
  parameters:
    type: object
    required: [name, organization, routes]
    properties:
      name:
        type: string
      organization:
        type: string
      routes:
        type: array
        items:
          type: object
          properties:
            message:
              type: string
      topic:
        type: string
`

// newAssistantLibrary holds a producing and a consuming template, plus a
// host template that must stay out of the catalog the model sees.
func newAssistantLibrary(t *testing.T) *templatetest.Library {
	t.Helper()
	return templatetest.NewLibrary(t, "v1.4.0", map[string]string{
		"extractor/template.yaml":           assistantExtractorYAML,
		"extractor/skeleton/README.md.tmpl": "{{ .name }} publishes {{ .publishes }}\n",
		"loader/template.yaml":              assistantLoaderYAML,
		"loader/skeleton/README.md.tmpl":    "{{ .name }}\n",
		"system-host/template.yaml":         "apiVersion: intropy.io/v1\nkind: Template\nmetadata:\n  name: system-host\nspec:\n  parameters:\n    type: object\n",
		"system-host/skeleton/README.md":    "host\n",
	})
}

// cannedChat answers each completion with the next scripted reply and
// records the conversations it was sent.
type cannedChat struct {
	replies []string
	seen    [][]chatMessage
}

func (c *cannedChat) chat(_ context.Context, msgs []chatMessage, _ json.RawMessage) (string, error) {
	c.seen = append(c.seen, msgs)
	if len(c.replies) == 0 {
		return "", errors.New("no reply scripted")
	}
	r := c.replies[0]
	c.replies = c.replies[1:]
	return r, nil
}

func assistantHandler(t *testing.T, root string, chat *cannedChat, org string) http.Handler {
	t.Helper()
	p := templateProviders(newAssistantLibrary(t).Source(t))
	if chat != nil {
		p.assistant = &assistantProvider{model: "test-model", chat: chat.chat}
	}
	h, api, err := newHandler(root, "test", p)
	if err != nil {
		t.Fatal(err)
	}
	api.organization = org
	return h
}

func decodePlanResponse(t *testing.T, rec *httptest.ResponseRecorder) planResponse {
	t.Helper()
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200: %s", rec.Code, rec.Body)
	}
	var got planResponse
	if err := json.Unmarshal(rec.Body.Bytes(), &got); err != nil {
		t.Fatal(err)
	}
	return got
}

const intakePlan = `{
  "summary": "Plan: two extractors publish RawPartnerMessage on one topic.",
  "steps": [
    {"template": "extractor", "name": "SftpIntake", "publishes": "RawPartnerMessage", "subscribe": "",
     "set": [{"key": "topic", "value": "inbound.raw"}], "why": "EDI files over SFTP"},
    {"template": "extractor", "name": "HttpIntake", "publishes": "RawPartnerMessage", "subscribe": "",
     "set": [{"key": "topic", "value": "inbound.raw"}], "why": "JSON over HTTP"}
  ]
}`

func TestAssistantStatusDisabledWithoutKey(t *testing.T) {
	h := assistantHandler(t, t.TempDir(), nil, "")
	rec := get(t, h, "/api/assistant")
	if !strings.Contains(rec.Body.String(), `"enabled": false`) {
		t.Errorf("status = %s", rec.Body)
	}
	if rec := postJSON(t, h, "/api/assistant/plan", `{"prompt":"x"}`); rec.Code != http.StatusServiceUnavailable {
		t.Errorf("plan status = %d, want 503", rec.Code)
	}
}

func TestAssistantPlanRendersCommands(t *testing.T) {
	chat := &cannedChat{replies: []string{intakePlan}}
	h := assistantHandler(t, t.TempDir(), chat, "Acme")

	got := decodePlanResponse(t, postJSON(t, h, "/api/assistant/plan",
		`{"prompt":"Partners send orders over SFTP and HTTP. Set up the intake.","system":"."}`))

	if len(got.Steps) != 3 {
		t.Fatalf("steps = %+v, want two creates and a host step", got.Steps)
	}
	first := got.Steps[0]
	if first.Error != "" {
		t.Fatalf("step error: %s", first.Error)
	}
	want := "intropy int create extractor -n SftpIntake --publishes RawPartnerMessage --set topic=inbound.raw --set organization=Acme --template-version v1.4.0 --no-input"
	if first.Command != want {
		t.Errorf("command =\n %s\nwant\n %s", first.Command, want)
	}
	if first.OutputDir != "sftp-intake" || first.Request == nil || first.Request.Publishes != "RawPartnerMessage" {
		t.Errorf("step = %+v", first)
	}
	if first.Values["publishes"] != "RawPartnerMessage" {
		t.Errorf("resolved values = %v", first.Values)
	}
	pub := first.Preview.Publishes
	if len(pub) != 1 || pub[0].Topic != "inbound.raw" || pub[0].Pubsub != "pubsub" {
		t.Errorf("preview = %+v", first.Preview)
	}
	host := got.Steps[2]
	if host.Kind != "sys-sync" || !strings.HasPrefix(host.Command, "intropy sys create -n ") {
		t.Errorf("host step = %+v", host)
	}

	// The model saw the component templates, never the host.
	prompt := chat.seen[0][0].Content
	if !strings.Contains(prompt, `"template": "loader"`) || strings.Contains(prompt, `"template": "system-host"`) {
		t.Errorf("catalog in prompt is wrong:\n%s", prompt)
	}
}

