	bad := `{"summary":"Plan: x","steps":[{"template":"extractor","name":"sftp-intake","publishes":"Raw","subscribe":"","set":[{"key":"port","value":"sftp"}],"why":"w"}]}`
	good := `{"summary":"Plan: x","steps":[{"template":"extractor","name":"SftpIntake","publishes":"Raw","subscribe":"","set":[],"why":"w"}]}`
	chat := &cannedChat{replies: []string{bad, good}}
	h := assistantHandler(t, t.TempDir(), chat, "Acme")

	got := decodePlanResponse(t, postJSON(t, h, "/api/assistant/plan", `{"prompt":"intake"}`))
	if len(chat.seen) != 2 {
