	}
	repair := chat.seen[1][len(chat.seen[1])-1].Content
	if !strings.Contains(repair, `unknown parameter "port"`) {
		t.Errorf("repair prompt = %s", repair)
	}
	if got.Steps[0].Error != "" {
		t.Errorf("repaired step still fails: %s", got.Steps[0].Error)
	}
}

