import { useEffect, useMemo, useRef, useState } from 'react'
import {
  api,
  type AssistantPlan,
  type AssistantStatus,
  type PlanStep,
  type TopologyComponent,
} from '../api'

interface Props {
  /** Root-relative system directory the plan targets ("." for the root). */
  system: string
  /** The components not yet created, for the canvas to draw as planned. */
  onPreview: (components: TopologyComponent[]) => void
  /** A step changed the workspace: a scaffold rendered or the host assembled. */
  onApplied: (step: PlanStep) => void
}

type StepState = 'pending' | 'running' | 'done' | 'failed'

interface StepRun {
  state: StepState
  output: string[]
}

const EXAMPLE =
  'Partners send orders, invoices and complaints as EDI files over SFTP and as JSON over HTTP. Set up the intake.'

// AssistantPanel turns a prose request into the CLI calls that build it and
// lists them beside the canvas. Planning is read-only; Apply runs each step
// through the same endpoints the create drawer and the host banner use, in
// order, and stops at the first failure so later steps never run against a
// workspace the plan did not expect.
export function AssistantPanel({ system, onPreview, onApplied }: Props) {
  const [status, setStatus] = useState<AssistantStatus | null>(null)
  const [prompt, setPrompt] = useState('')
  const [planning, setPlanning] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [plan, setPlan] = useState<AssistantPlan | null>(null)
  const [runs, setRuns] = useState<Record<string, StepRun>>({})
  const [applying, setApplying] = useState(false)
  const abort = useRef<AbortController | null>(null)

  useEffect(() => {
    api
      .assistantStatus()
      .then(setStatus)
      .catch(() => setStatus({ enabled: false }))
  }, [])

  useEffect(() => () => abort.current?.abort(), [])

  // The canvas draws every planned component that has not rendered yet; a
  // rendered one shows up as a scaffolded ghost through the normal refresh.
  useEffect(() => {
    const pending = (plan?.steps ?? []).filter(
      (s) => s.preview && !s.error && runs[s.id]?.state !== 'done',
    )
    onPreview(pending.map((s) => s.preview!))
  }, [plan, runs, onPreview])

  const invalid = useMemo(() => (plan?.steps ?? []).filter((s) => s.error).length, [plan])
  const allDone = !!plan && plan.steps.every((s) => runs[s.id]?.state === 'done')

  const submit = () => {
    const text = prompt.trim()
    if (!text || planning) return
    abort.current?.abort()
    const ctl = new AbortController()
    abort.current = ctl
    setPlanning(true)
    setError(null)
    setPlan(null)
    setRuns({})
    api
      .plan(text, system, ctl.signal)
      .then(setPlan)
      .catch((e: unknown) => {
        if (!ctl.signal.aborted) setError(e instanceof Error ? e.message : String(e))
      })
      .finally(() => {
        if (abort.current === ctl) setPlanning(false)
      })
  }

  const setRun = (id: string, run: StepRun) => setRuns((r) => ({ ...r, [id]: run }))

  const apply = async () => {
    if (!plan || invalid > 0 || applying) return
    setApplying(true)
    for (const step of plan.steps) {
      if (runs[step.id]?.state === 'done') continue
      setRun(step.id, { state: 'running', output: [] })
      try {
        const output = await runStep(step)
        setRun(step.id, { state: 'done', output })
        onApplied(step)
      } catch (e) {
        setRun(step.id, { state: 'failed', output: [e instanceof Error ? e.message : String(e)] })
        break
      }
    }
    setApplying(false)
  }

  const discard = () => {
    abort.current?.abort()
    setPlan(null)
    setRuns({})
    setError(null)
  }

  if (status && !status.enabled) {
    return (
      <aside className="ai-panel">
        <PanelHead />
        <p className="ai-muted">
          The assistant plans with Berget AI. Set <code>BERGET_API_KEY</code> and restart{' '}
          <code>intropy dashboard</code> to enable it.
        </p>
      </aside>
    )
  }

  return (
    <aside className="ai-panel">
      <PanelHead model={status?.model} />
      <form
        className="ai-prompt"
        onSubmit={(e) => {
          e.preventDefault()
          submit()
        }}
      >
        <textarea
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
              e.preventDefault()
              submit()
            }
          }}
          placeholder={EXAMPLE}
          rows={4}
          aria-label="Describe the integration to build"
          disabled={applying}
        />
        <div className="ai-prompt-actions">
          {!prompt && (
            <button type="button" className="ai-link" onClick={() => setPrompt(EXAMPLE)}>
              use example
            </button>
          )}
          <button
            type="submit"
            className="ai-primary"
            disabled={!prompt.trim() || planning || applying}
            title="Plan (⌘↵)"
          >
            {planning ? 'Planning…' : 'Plan'}
          </button>
        </div>
      </form>

      {planning && <p className="ai-muted ai-pulse">asking {status?.model ?? 'the model'}…</p>}
      {error && <div className="banner error">{error}</div>}

      {plan && (
        <div className="ai-plan">
          {plan.summary && <p className="ai-summary">{plan.summary}</p>}
          {plan.steps.length === 0 && <p className="ai-muted">the model proposed no steps</p>}
          <ol className="ai-steps">
            {plan.steps.map((s) => (
              <Step key={s.id} step={s} run={runs[s.id]} version={plan.version} />
            ))}
          </ol>
          {invalid > 0 && (
            <p className="ai-error-note">
              {invalid === 1 ? '1 step does' : `${invalid} steps do`} not validate against{' '}
              templates {plan.version}; rephrase the request and plan again
            </p>
          )}
          <div className="ai-actions">
            <button
              type="button"
              className="ai-primary"
              onClick={apply}
              disabled={invalid > 0 || applying || allDone || plan.steps.length === 0}
            >
              {applying ? 'Applying…' : allDone ? 'Applied' : `Apply ${plan.steps.length} steps`}
            </button>
            <CopyButton
              text={plan.steps.map((s) => s.command).join('\n')}
              label="Copy as script"
            />
            <button type="button" className="ai-secondary" onClick={discard} disabled={applying}>
              Discard
            </button>
          </div>
        </div>
      )}
    </aside>
  )
}

function PanelHead({ model }: { model?: string }) {
  return (
    <div className="ai-head">
      <span className="ai-title">Assistant</span>
      {model && (
        <span className="ai-model" title="Berget AI model">
          {model.split('/').pop()}
        </span>
      )}
    </div>
  )
}

// Step renders one command the way a terminal would show it: the prompt
// line, what it wrote once run, and — for a create — the scaffold record it
// will write, from the values the server already resolved.
function Step({ step, run, version }: { step: PlanStep; run?: StepRun; version: string }) {
  const state: StepState | 'invalid' = step.error ? 'invalid' : (run?.state ?? 'pending')
  const record =
    step.kind === 'int-create' && step.values
      ? JSON.stringify(
          { template: step.template, version, blockKind: step.blockKind, ...step.values },
          null,
          2,
        )
      : null
  return (
    <li className={`ai-step ${state}`}>
      <div className="ai-cmd">
        <span className="ai-state" aria-label={state} title={state} />
        <code>
          <span className="ai-dollar">$ </span>
          {step.command}
        </code>
        <CopyButton text={step.command} label="Copy" compact />
      </div>
      {step.why && <div className="ai-why">{step.why}</div>}
      {step.error && <pre className="ai-out err">{step.error}</pre>}
      {run && run.output.length > 0 && (
        <pre className={`ai-out${run.state === 'failed' ? ' err' : ''}`}>{run.output.join('\n')}</pre>
      )}
      {record && (
        <details className="ai-record">
          <summary>
            {step.outputDir}/.intropy/scaffold.json
            {run?.state !== 'done' && <span className="ai-muted"> (planned)</span>}
          </summary>
          <pre className="ai-diff">
            {record
              .split('\n')
              .map((l) => `+ ${l}`)
              .join('\n')}
          </pre>
        </details>
      )}
    </li>
  )
}

function CopyButton({ text, label, compact }: { text: string; label: string; compact?: boolean }) {
  const [copied, setCopied] = useState(false)
  return (
    <button
      type="button"
      className={compact ? 'ai-copy' : 'ai-secondary'}
      onClick={() => {
        navigator.clipboard
          ?.writeText(text)
          .then(() => {
            setCopied(true)
            setTimeout(() => setCopied(false), 1200)
          })
          .catch(() => {})
      }}
      title={label}
    >
      {copied ? 'Copied' : label}
    </button>
  )
}

// runStep applies one step and returns the lines a terminal would have shown.
async function runStep(step: PlanStep): Promise<string[]> {
  if (step.kind === 'int-create') {
    if (!step.template || !step.request) throw new Error('step has no create request')
    const res = await api.createTemplate(step.template, step.request)
    return [
      ...(res.diagnostics ?? []),
      `rendered ${res.template}@${res.version} into ${res.outputDir}/`,
      ...(res.dependencies ?? []).map((d) => `${d.action} ${d.template} into ${d.outputDir}/`),
      `wrote ${res.outputDir}/.intropy/scaffold.json`,
    ]
  }
  const res = await api.syncSystem(step.system ?? '.')
  const lines = [...(res.diagnostics ?? [])]
  if (res.action === 'none') lines.push('host is up to date')
  else {
    lines.push(`${res.action === 'create' ? 'created' : 'updated'} ${res.system ?? 'host'} in ${res.hostDir}/`)
    if (res.added?.length) lines.push(`added ${res.added.join(', ')}`)
  }
  return lines
}

