func (s *apiServer) planAssistant(w http.ResponseWriter, r *http.Request) {
	if len(s.engines()) == 0 {
		writeError(w, http.StatusServiceUnavailable, "assistant is not configured\\nset BERGET_API_KEY or TYPESAFE_API_KEY and restart 'intropy dashboard'")
