// planWithBerget asks the generative model for the whole plan, validates
// it, and gives the model one chance to repair what failed.
func (s *apiServer) planWithBerget(ctx context.Context, in planInput) (planResponse, error) {
	messages := []chatMessage{
		{Role: "system", Content: assistantSystemPrompt(in.catalog, in.existing, s.organization)},
		{Role: "user", Content: in.prompt},
	}
