package dashboard

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"math"
	"net/http"
	"regexp"
	"sort"
	"strings"
	"time"
	"unicode"

	"github.com/huandu/xstrings"
	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// The Jev engine plans with TypeSafe's Jev, a decision model: it answers
// typed questions (yes/no, pick one of these) with calibrated probabilities
// and never generates text. So the plan is assembled in code from a fixed
// sequence of decisions:
//
//  1. one fan-out request asks, in parallel, which component kinds the
//     request needs, which sources and destinations it names, which words
//     name its subject and data, and — speculatively, for every template —
//     whether each parameter is stated and which literal states it;
//  2. one follow-up request merges sources or destinations that name the
//     same thing twice and picks a template per component when a kind has
//     several;
//  3. code turns the answers into `int create` steps: names and message
//     names are built from conventions over the picked words, defaults
//     apply where the request is silent, and anything below the confidence
//     bar comes back as a clarification instead of a guess.
//
// Free-form values are never produced by the model. Candidates come from
// the request text, the workspace and the template schema; Jev only selects
// among them, with a "none" escape, as TypeSafe recommends.

// DefaultJevURL is TypeSafe's API base.
const DefaultJevURL = "https://api.typesafe.ai"

// DefaultJevModel follows TypeSafe's latest Jev release.
const DefaultJevModel = "jev-latest"

// Decision thresholds. A yes/no counts at or beyond the outer bands and is
// asked back in between; a pick needs the confidence floor TypeSafe's docs
// suggest for acting without a human.
const (
	jevYes    = 0.65
	jevNo     = 0.35
	jevAccept = 0.6
)

// maxCandidates bounds the words offered per question: Choice takes 255
// options, but accuracy drops with irrelevant detail long before that.
const maxCandidates = 24

// JevConfig selects the TypeSafe endpoint the Jev engine plans with. An
// empty APIKey disables it.
type JevConfig struct {
	BaseURL string
	APIKey  string
	Model   string
}

type jevProvider struct {
	model string
	ask   jevFunc
}

// jevFunc evaluates one batch of questions. Production posts to TypeSafe;
// tests substitute scripted answers.
type jevFunc func(ctx context.Context, req jevRequest) (jevResponse, error)

type jevRequest struct {
	Model     string                 `json:"model"`
	State     any                    `json:"state"`
	Questions map[string]jevQuestion `json:"questions"`
}

type jevQuestion struct {
	Type         string          `json:"type"`
	Instructions string          `json:"instructions"`
	Criteria     json.RawMessage `json:"criteria,omitempty"`
}

type jevAnswer struct {
	Type          string             `json:"type"`
	Noul          float64            `json:"noul"`
	Choice        string             `json:"choice"`
	Probabilities map[string]float64 `json:"probabilities"`
	Confidence    float64            `json:"confidence"`
}

type jevResponse struct {
	Model   string               `json:"model"`
	Answers map[string]jevAnswer `json:"answers"`
	Usage   struct {
		InputTokens  int `json:"input_tokens"`
		OutputTokens int `json:"output_tokens"`
	} `json:"usage"`
}

func newJevProvider(cfg JevConfig) *jevProvider {
	if cfg.APIKey == "" {
		return nil
	}
	if cfg.BaseURL == "" {
		cfg.BaseURL = DefaultJevURL
	}
	if cfg.Model == "" {
		cfg.Model = DefaultJevModel
	}
	client := &http.Client{Timeout: 30 * time.Second}
	return &jevProvider{model: cfg.Model, ask: typesafeAsk(client, cfg)}
}

// typesafeAsk posts to /v1/systemone, retrying the two statuses TypeSafe
// documents as transient (429 rate limit, 529 overloaded).
func typesafeAsk(client *http.Client, cfg JevConfig) jevFunc {
	endpoint := strings.TrimRight(cfg.BaseURL, "/") + "/v1/systemone"
	return func(ctx context.Context, req jevRequest) (jevResponse, error) {
		body, err := json.Marshal(req)
		if err != nil {
			return jevResponse{}, err
		}
		for attempt := 0; ; attempt++ {
			hreq, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(body))
			if err != nil {
				return jevResponse{}, err
			}
			hreq.Header.Set("Authorization", "Bearer "+cfg.APIKey)
			hreq.Header.Set("Content-Type", "application/json")
			resp, err := client.Do(hreq)
			if err != nil {
				return jevResponse{}, fmt.Errorf("typesafe: %w", err)
			}
			raw, err := io.ReadAll(io.LimitReader(resp.Body, 4<<20))
			resp.Body.Close()
			if err != nil {
				return jevResponse{}, fmt.Errorf("typesafe: read response: %w", err)
			}
			if (resp.StatusCode == http.StatusTooManyRequests || resp.StatusCode == 529) && attempt < 2 {
				select {
				case <-time.After(time.Duration(500<<attempt) * time.Millisecond):
					continue
				case <-ctx.Done():
					return jevResponse{}, ctx.Err()
				}
			}
			if resp.StatusCode != http.StatusOK {
				return jevResponse{}, fmt.Errorf("typesafe: %s: %s", resp.Status, strings.TrimSpace(string(raw)))
			}
			var out jevResponse
			if err := json.Unmarshal(raw, &out); err != nil {
				return jevResponse{}, fmt.Errorf("typesafe: decode response: %w", err)
			}
			return out, nil
		}
	}
}

// option is one Choice option; an empty desc is sent as null.
type option struct{ key, desc string }

// noulQ builds a yes/no question with aligned criteria — inverted or
// mismatched criteria are a documented accuracy hazard.
func noulQ(instructions, yes, no string) jevQuestion {
	crit, _ := json.Marshal(map[string]string{"true": yes, "false": no})
	return jevQuestion{Type: "noul", Instructions: instructions, Criteria: crit}
}

// choiceQ builds a Choice question with its options in the given order.
// encoding/json sorts map keys, and Jev leans toward the first option, so
// the order is written out by hand: candidates first, escapes last.
func choiceQ(instructions string, opts []option) jevQuestion {
	var b bytes.Buffer
	b.WriteByte('{')
	for i, o := range opts {
		if i > 0 {
			b.WriteByte(',')
		}
		k, _ := json.Marshal(o.key)
		b.Write(k)
		b.WriteByte(':')
		if o.desc == "" {
			b.WriteString("null")
		} else {
			v, _ := json.Marshal(o.desc)
			b.Write(v)
		}
	}
	b.WriteByte('}')
	return jevQuestion{Type: "choice", Instructions: instructions, Criteria: b.Bytes()}
}

// jevSession accumulates one plan's questions, answers, outcomes and cost.
type jevSession struct {
	p       *jevProvider
	state   any
	order   []string
	asked   map[string]jevQuestion
	got     map[string]jevAnswer
	outcome map[string]string
	usage   engineUsage
	model   string
}

func newJevSession(p *jevProvider, prompt string) *jevSession {
	return &jevSession{
		p:       p,
		state:   map[string]string{"request": prompt},
		asked:   map[string]jevQuestion{},
		got:     map[string]jevAnswer{},
		outcome: map[string]string{},
		model:   p.model,
	}
}

// ask sends one batch. An empty batch costs nothing and sends nothing.
func (j *jevSession) ask(ctx context.Context, qs map[string]jevQuestion) error {
	if len(qs) == 0 {
		return nil
	}
	ids := make([]string, 0, len(qs))
	for id := range qs {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	resp, err := j.p.ask(ctx, jevRequest{Model: j.p.model, State: j.state, Questions: qs})
	if err != nil {
		return err
	}
	j.usage.Calls++
	j.usage.InputTokens += resp.Usage.InputTokens
	j.usage.OutputTokens += resp.Usage.OutputTokens
	if resp.Model != "" {
		j.model = resp.Model
	}
	for _, id := range ids {
		j.order = append(j.order, id)
		j.asked[id] = qs[id]
		if a, ok := resp.Answers[id]; ok {
			j.got[id] = a
		}
	}
	return nil
}

// verdict is a yes/no answer in three bands.
type verdict int

const (
	vNo verdict = iota
	vUnsure
	vYes
)

// yes reads a yes/no decision, letting a user's answer override it.
func (j *jevSession) yes(id string, answers map[string]string) verdict {
	if a, ok := answers[id]; ok {
		j.outcome[id] = "answered"
		if strings.EqualFold(a, "yes") || a == "true" {
			return vYes
		}
		return vNo
	}
	p := j.got[id].Noul
	switch {
	case p >= jevYes:
		return vYes
	case p <= jevNo:
		return vNo
	}
	return vUnsure
}

// pick reads a choice. ok is false below the confidence floor; the caller
// decides between a clarification and a default.
func (j *jevSession) pick(id string, answers map[string]string) (string, bool) {
	if a, ok := answers[id]; ok && a != "" {
		j.outcome[id] = "answered"
		return a, true
	}
	a, ok := j.got[id]
	if !ok {
		return "", false
	}
	return a.Choice, a.Confidence >= jevAccept
}

// ranked returns a choice's options by probability, escapes excluded.
func (j *jevSession) ranked(id string, n int, skip ...string) []clarifOption {
	var out []clarifOption
	for k, p := range j.got[id].Probabilities {
		if contains(skip, k) {
			continue
		}
		out = append(out, clarifOption{Value: k, Probability: math.Round(p*100) / 100})
	}
	sort.Slice(out, func(a, b int) bool {
		if out[a].Probability != out[b].Probability {
			return out[a].Probability > out[b].Probability
		}
		return out[a].Value < out[b].Value
	})
	if len(out) > n {
		out = out[:n]
	}
	return out
}

func (j *jevSession) mark(id, outcome string) {
	if _, answered := j.outcome[id]; answered && j.outcome[id] == "answered" {
		return
	}
	j.outcome[id] = outcome
}

// trace renders every question in ask order with what the plan made of it.
func (j *jevSession) trace() []decision {
	out := make([]decision, 0, len(j.order))
	for _, id := range j.order {
		q, a := j.asked[id], j.got[id]
		d := decision{ID: id, Question: q.Instructions, Outcome: j.outcome[id]}
		if d.Outcome == "" {
			d.Outcome = "unused"
		}
		switch a.Type {
		case "noul":
			d.Answer = fmt.Sprintf("yes %.2f", a.Noul)
			d.Confidence = math.Round(math.Abs(2*a.Noul-1)*100) / 100
		case "choice":
			d.Answer = fmt.Sprintf("%s %.2f", a.Choice, a.Probabilities[a.Choice])
			d.Confidence = math.Round(a.Confidence*100) / 100
		default:
			d.Answer = "no answer"
		}
		out = append(out, d)
	}
	return out
}

// channel is a way data crosses the system boundary, offered to Jev as a
// source and destination candidate.
type channel struct{ key, label, desc string }

var channels = []channel{
	{"sftp", "SFTP", "files transferred over SFTP or FTP"},
	{"http", "HTTP", "HTTP requests, a REST or web API, or webhooks"},
	{"file", "File share", "files placed in a local folder or network file share (not SFTP)"},
	{"email", "Email", "email messages or attachments"},
	{"queue", "Queue", "a message queue or broker such as Service Bus, Kafka or RabbitMQ"},
	{"database", "Database", "reading from or writing to a database table"},
	{"blob", "Blob", "blob or object storage such as Azure Blob Storage or S3"},
}

// channelWords are the request words a channel candidate already covers,
// plus format names, so neither is offered again as a noun.
var channelWords = map[string]bool{
	"sftp": true, "ftp": true, "ftps": true, "http": true, "https": true, "rest": true, "api": true,
	"webhook": true, "file": true, "folder": true, "share": true, "email": true, "mail": true,
	"queue": true, "broker": true, "kafka": true, "database": true, "db": true, "table": true,
	"blob": true, "storage": true, "s3": true, "bucket": true,
	"edi": true, "json": true, "xml": true, "csv": true, "format": true,
}

var stopwords = map[string]bool{
	"a": true, "an": true, "and": true, "or": true, "the": true, "to": true, "of": true, "in": true,
	"on": true, "for": true, "from": true, "into": true, "over": true, "via": true, "as": true,
	"by": true, "with": true, "our": true, "their": true, "its": true, "it": true, "they": true,
	"we": true, "us": true, "is": true, "are": true, "be": true, "must": true, "should": true,
	"need": true, "needs": true, "want": true, "set": true, "up": true, "setup": true, "send": true,
	"sends": true, "receive": true, "receives": true, "deliver": true, "delivered": true,
	"archive": true, "copy": true, "incoming": true, "outgoing": true, "arriving": true,
	"arrive": true, "every": true, "each": true, "all": true, "also": true, "then": true,
	"that": true, "this": true, "these": true, "those": true, "when": true, "new": true,
	"get": true, "put": true, "write": true, "read": true, "pull": true, "push": true,
	"data": true, "system": true, "systems": true, "intake": true, "please": true, "too": true,
}

var wordRe = regexp.MustCompile(`[A-Za-z][A-Za-z0-9]*`)

// requestNouns extracts the content words of a request, singularized and
// deduplicated in order — candidates for subject, data, source and
// destination picks. Over-inclusion is cheap: Jev rejects what is not one.
func requestNouns(prompt string) []string {
	var out []string
	seen := map[string]bool{}
	for _, w := range wordRe.FindAllString(prompt, -1) {
		lw := singular(strings.ToLower(w))
		if len(lw) < 3 || stopwords[lw] || stopwords[strings.ToLower(w)] || channelWords[lw] || seen[lw] {
			continue
		}
		seen[lw] = true
		out = append(out, lw)
		if len(out) == maxCandidates {
			break
		}
	}
	return out
}

func singular(w string) string {
	switch {
	case strings.HasSuffix(w, "ies") && len(w) > 4:
		return w[:len(w)-3] + "y"
	case strings.HasSuffix(w, "sses"):
		return w[:len(w)-2]
	case strings.HasSuffix(w, "s") && !strings.HasSuffix(w, "ss") && len(w) > 3:
		return w[:len(w)-1]
	}
	return w
}

// properNouns are capitalized words that do not open a sentence and are
// not acronyms — the organization candidates.
func properNouns(prompt string) []string {
	var out []string
	seen := map[string]bool{}
	sentenceStart := true
	for _, tok := range strings.Fields(prompt) {
		w := strings.TrimFunc(tok, func(r rune) bool { return !unicode.IsLetter(r) && !unicode.IsDigit(r) })
		if w != "" && !sentenceStart && unicode.IsUpper(rune(w[0])) && strings.ToUpper(w) != w && !seen[w] {
			seen[w] = true
			out = append(out, w)
		}
		sentenceStart = strings.HasSuffix(tok, ".") || strings.HasSuffix(tok, "!") || strings.HasSuffix(tok, "?")
	}
	return out
}

var literalRe = regexp.MustCompile(`"[^"]+"|'[^']+'|[A-Za-z0-9_][A-Za-z0-9_.:/@-]*[A-Za-z0-9_]`)

// literalCandidates are the request's spans that could be a parameter
// value: quoted strings, and tokens carrying a digit or a separator
// (inbound.raw, urn:acme:x, 300) — or matching the field's own pattern.
func literalCandidates(prompt string, f template.FieldSpec) []string {
	var pattern *regexp.Regexp
	if f.Pattern != "" {
		pattern, _ = regexp.Compile(f.Pattern)
	}
	var out []string
	seen := map[string]bool{}
	for _, m := range literalRe.FindAllString(prompt, -1) {
		v := strings.Trim(m, `"'`)
		structured := strings.ContainsAny(v, ".:/@-0123456789") || strings.HasPrefix(m, `"`) || strings.HasPrefix(m, "'")
		if pattern != nil && pattern.MatchString(v) {
			structured = true
		}
		if !structured || seen[v] {
			continue
		}
		seen[v] = true
		out = append(out, v)
		if len(out) == maxCandidates {
			break
		}
	}
	return out
}

// kindQuestion asks whether the request needs a component of one kind.
// Each is literal and single-judgment, as Jev reads questions at face value.
func kindQuestion(ct catalogTemplate) jevQuestion {
	switch ct.BlockKind {
	case template.BlockKindExtractor:
		return noulQ("Does `request` ask to bring data into the system from an external source?",
			"data must be received, collected or taken in from outside", "nothing is brought in from outside")
	case template.BlockKindLoader:
		return noulQ("Does `request` ask to deliver, write or store data from the system in an external destination?",
			"data must be sent, written or archived somewhere outside", "nothing is sent anywhere outside")
	case "transactional-integration":
		return noulQ("Does `request` ask for a scheduled job that moves data directly from one external system to another without other consumers?",
			"one direct point-to-point transfer", "data is taken in or delivered without a direct point-to-point job")
	}
	return noulQ(fmt.Sprintf("Does `request` need this component: %s?", truncate(ct.Description, 200)),
		"the component is needed", "the component is not needed")
}

// jevInstance is one component the plan will create.
type jevInstance struct {
	key      string // channel key or noun the component is named after
	kind     string // block kind
	template string
	name     string
	message  string
}

// clarifications collects questions for the user, deduplicated by ID.
type clarifications struct{ list []clarification }

func (c *clarifications) add(q clarification) {
	for _, e := range c.list {
		if e.ID == q.ID {
			return
		}
	}
	c.list = append(c.list, q)
}

// planWithJev runs the decision sequence and builds steps from it.
func (s *apiServer) planWithJev(ctx context.Context, in planInput) (planResponse, error) {
	j := newJevSession(s.jev, in.prompt)
	ans := in.answers
	if ans == nil {
		ans = map[string]string{}
	}
	nouns := requestNouns(in.prompt)
	templates := sortedTemplates(in.catalog)

	// Round 1: everything that depends only on the request, in one call.
	r1 := map[string]jevQuestion{}
	for _, ct := range templates {
		r1["tpl."+ct.Name] = kindQuestion(ct)
	}
	r1["tpl.none"] = noulQ("Does `request` ask for work beyond moving data in or out, such as transforming, validating, enriching or reporting on it?",
		"it asks for processing beyond moving data", "it only asks to move data in or out")
	for _, ch := range channels {
		r1["src."+ch.key] = noulQ(fmt.Sprintf("Does `request` say data arrives into the system as %s?", ch.desc),
			ch.label+" is how data comes in", ch.label+" is not mentioned as an inbound channel")
		r1["dst."+ch.key] = noulQ(fmt.Sprintf("Does `request` say data must be delivered or stored as %s?", ch.desc),
			ch.label+" is where data goes out", ch.label+" is not mentioned as a destination")
	}
	for _, n := range nouns {
		r1["srcsys."+n] = noulQ(fmt.Sprintf("Does `request` name %q as an external system or party that data comes from?", n),
			n+" sends or provides the data", n+" is the data itself, a destination, or not a sender")
		r1["dstsys."+n] = noulQ(fmt.Sprintf("Does `request` name %q as an external system that data must be delivered to or stored in?", n),
			n+" receives or stores the data", n+" is the data itself, a source, or not a destination")
	}
	if len(nouns) > 0 {
		opts := make([]option, 0, len(nouns)+1)
		for _, n := range nouns {
			opts = append(opts, option{key: n})
		}
		r1["subject"] = choiceQ("Which word in `request` names the party or system that sends or owns the data?",
			append(opts, option{"none", "none of these names a party or system"}))
		r1["data"] = choiceQ("Which word in `request` names the kind of data being moved?",
			append(append([]option{}, opts...),
				option{"mixed", "several different kinds of documents are listed"},
				option{"none", "none of these names the data"}))
	}
	needOrg := s.organization == "" && ans["organization"] == ""
	if orgs := properNouns(in.prompt); needOrg && len(orgs) > 0 {
		opts := make([]option, 0, len(orgs)+1)
		for _, o := range orgs {
			opts = append(opts, option{key: o})
		}
		r1["organization"] = choiceQ("Which word in `request` is the name of the organization that runs this integration?",
			append(opts, option{"none", "the request names no organization"}))
	}
	existingMsgs := existingMessages(in.existing)
	if len(existingMsgs) > 0 {
		opts := make([]option, 0, len(existingMsgs)+1)
		for _, m := range existingMsgs {
			opts = append(opts, option{key: m.name, desc: "message published by " + m.publisher})
		}
		r1["reuse"] = choiceQ("Which existing message carries the data `request` is about?",
			append(opts, option{"new", "none of these; the request is about different data"}))
	}
	paramQuestions(r1, in.prompt, templates)
	if err := j.ask(ctx, r1); err != nil {
		return planResponse{}, err
	}

	var clar clarifications
	var warnings []string

	// Template selection: every kind the request needs, possibly several.
	selected := map[string]bool{}
	for _, ct := range templates {
		id := "tpl." + ct.Name
		switch j.yes(id, ans) {
		case vYes:
			selected[ct.BlockKind] = true
			j.mark(id, "accepted")
		case vNo:
			j.mark(id, "rejected")
		default:
			j.mark(id, "clarify")
			clar.add(yesNo(id, fmt.Sprintf("Does the request need a %s (template %s)?", kindLabel(ct.BlockKind), ct.Name)))
		}
	}
	if selected["transactional-integration"] && (selected[template.BlockKindExtractor] || selected[template.BlockKindLoader]) {
		delete(selected, "transactional-integration")
		warnings = append(warnings, "the request also reads as a point-to-point job; planned it as messaging components instead")
	}
	if j.yes("tpl.none", ans) == vYes {
		j.mark("tpl.none", "accepted")
		warnings = append(warnings, "part of the request (transforming, validating or reporting) has no template; plan it separately")
	} else {
		j.mark("tpl.none", "rejected")
	}

	// Sources and destinations. Named channels define the intake; a named
	// sender only stands in when no channel is named, since "partners send
	// over SFTP and HTTP" is two intakes, not three.
	var sources, dests []string
	if selected[template.BlockKindExtractor] {
		sources = s.discover(j, &clar, ans, "src", channelKeys(), "Should the plan include an intake that receives data via %s?")
		if len(sources) == 0 {
			sources = s.discover(j, &clar, ans, "srcsys", nouns, "Does data come from %s?")
		}
	}
	if selected[template.BlockKindLoader] {
		dests = append(s.discover(j, &clar, ans, "dst", channelKeys(), "Should the plan include a delivery via %s?"),
			s.discover(j, &clar, ans, "dstsys", nouns, "Must data be delivered to %s?")...)
	}

	// Round 2: merge duplicates and pick templates per component.
	r2 := map[string]jevQuestion{}
	samePairs(r2, "src", sources, "source")
	samePairs(r2, "dst", dests, "destination")
	byKind := map[string][]catalogTemplate{}
	for _, ct := range templates {
		byKind[ct.BlockKind] = append(byKind[ct.BlockKind], ct)
	}
	tplFor := func(kind, key string) string { return "tplfor." + kind + "." + key }
	for kind, list := range byKind {
		if len(list) < 2 || !selected[kind] {
			continue
		}
		keys := sources
		if kind == template.BlockKindLoader {
			keys = dests
		}
		for _, k := range keys {
			opts := make([]option, 0, len(list))
			for _, ct := range list {
				opts = append(opts, option{key: ct.Name, desc: truncate(ct.Description, 200)})
			}
			r2[tplFor(kind, k)] = choiceQ(fmt.Sprintf("Which template fits the component that handles %s in `request`?", channelLabel(k)), opts)
		}
	}
	if err := j.ask(ctx, r2); err != nil {
		return planResponse{}, err
	}
	sources = merge(j, ans, "src", sources)
	dests = merge(j, ans, "dst", dests)

	// Names: subject and data words, picked by Jev, composed by convention.
	subject := s.word(j, &clar, ans, "subject", "Which word names who sends or owns the data?", "none")
	data := s.word(j, &clar, ans, "data", "Which word names the kind of data being moved?", "none", "mixed")
	if data == "" && j.got["data"].Choice == "mixed" {
		data = "mixed"
	}

	// Organization: the configured one, an answer, or Jev's pick of a
	// proper noun in the request; never invented.
	org := s.organization
	if org == "" {
		org = ans["organization"]
	}
	if org == "" {
		if v, ok := j.pick("organization", ans); ok && v != "none" {
			org = v
			j.mark("organization", "accepted")
		} else {
			if _, asked := j.asked["organization"]; asked {
				j.mark("organization", "clarify")
			}
			clar.add(clarification{ID: "organization", Kind: "text",
				Question: "Which organization runs this integration? (PascalCase, e.g. Acme)", Pattern: "^[A-Z][A-Za-z0-9]*$"})
		}
	}

	// Messages: reuse an existing one when Jev says the request is about
	// it, otherwise compose one from the subject and data words.
	reuse := ""
	if _, asked := j.asked["reuse"]; asked {
		if v, ok := j.pick("reuse", ans); ok {
			j.mark("reuse", "accepted")
			if v != "new" {
				reuse = v
			}
		} else {
			j.mark("reuse", "clarify")
			opts := j.ranked("reuse", 4)
			clar.add(clarification{ID: "reuse", Kind: "choice", Options: opts,
				Question: "Is the request about one of the system's existing messages? Pick \"new\" if not."})
		}
	}
	newMessage := composeMessage(subject, data)

	if len(clar.list) > 0 {
		return planResponse{
			Summary:        fmt.Sprintf("Jev needs %d answer(s) before it can plan.", len(clar.list)),
			Model:          j.model,
			Clarifications: clar.list,
			Trace:          j.trace(),
			Usage:          j.usage,
		}, nil
	}

	// Instances.
	var instances []jevInstance
	taken := map[string]int{}
	name := func(parts ...string) string {
		var b strings.Builder
		prev := ""
		for _, p := range parts {
			if p == "" || p == "mixed" || strings.EqualFold(p, prev) {
				continue
			}
			b.WriteString(xstrings.ToPascalCase(p))
			prev = p
		}
		n := b.String()
		taken[n]++
		if taken[n] > 1 {
			n = fmt.Sprintf("%s%d", n, taken[n])
		}
		return n
	}
	pickTemplate := func(kind, key string) string {
		list := byKind[kind]
		if len(list) == 1 {
			return list[0].Name
		}
		id := tplFor(kind, key)
		v, ok := j.pick(id, ans)
		j.mark(id, map[bool]string{true: "accepted", false: "accepted (low confidence)"}[ok])
		return v
	}
	extractorMsg := reuse
	if extractorMsg == "" {
		extractorMsg = newMessage
	}
	for _, src := range sources {
		instances = append(instances, jevInstance{key: src, kind: template.BlockKindExtractor,
			template: pickTemplate(template.BlockKindExtractor, src),
			name:     name(src, subject, "intake"), message: extractorMsg})
	}
	loaderMsg := ""
	switch {
	case len(sources) > 0:
		loaderMsg = extractorMsg
	case reuse != "":
		loaderMsg = reuse
	case ans["loader.message"] != "":
		loaderMsg = ans["loader.message"]
	}
	if len(dests) > 0 && loaderMsg == "" {
		opts := make([]clarifOption, 0, len(existingMsgs))
		for _, m := range existingMsgs {
			opts = append(opts, clarifOption{Value: m.name, Label: "published by " + m.publisher})
		}
		kind := "text"
		if len(opts) > 0 {
			kind = "choice"
		}
		clar.add(clarification{ID: "loader.message", Kind: kind, Options: opts,
			Question: "Which message should the delivery components subscribe to?"})
	}
	dataWord := data
	if dataWord == "" || dataWord == "mixed" {
		dataWord = subject
	}
	for _, dst := range dests {
		instances = append(instances, jevInstance{key: dst, kind: template.BlockKindLoader,
			template: pickTemplate(template.BlockKindLoader, dst),
			name:     name(dst, dataWord, "loader"), message: loaderMsg})
	}
	if selected["transactional-integration"] {
		instances = append(instances, jevInstance{key: subject, kind: "transactional-integration",
			template: byKind["transactional-integration"][0].Name, name: name(subject, "sync")})
	}

	// Parameters: per template, from the speculative round-1 questions.
	params := map[string][]llmSet{}
	for _, inst := range instances {
		if _, done := params[inst.template]; done {
			continue
		}
		params[inst.template] = s.resolveParams(j, &clar, ans, in.catalog[inst.template], in.prompt)
	}
	if len(clar.list) > 0 {
		return planResponse{
			Summary:        fmt.Sprintf("Jev needs %d answer(s) before it can plan.", len(clar.list)),
			Model:          j.model,
			Clarifications: clar.list,
			Trace:          j.trace(),
			Usage:          j.usage,
		}, nil
	}

	plan := llmPlan{Summary: jevSummary(instances, sources, dests)}
	if len(instances) == 0 {
		plan.Summary = "Plan: no suitable template — the request asks for nothing the library's components do."
	}
	producerTopics := producerTopics(in.existing, instances, params)
	for _, inst := range instances {
		st := llmStep{Template: inst.template, Name: inst.name, Set: append([]llmSet{}, params[inst.template]...)}
		if org != "" && s.organization == "" {
			st.Set = append(st.Set, llmSet{Key: "organization", Value: org})
		}
		switch inst.kind {
		case template.BlockKindExtractor:
			st.Publishes = inst.message
			st.Why = fmt.Sprintf("receives data via %s and publishes %s", channelLabel(inst.key), inst.message)
		case template.BlockKindLoader:
			st.Subscribe = inst.message
			st.Why = fmt.Sprintf("subscribes to %s and delivers it to %s", inst.message, channelLabel(inst.key))
			// Dependency: a subscriber listens where the message is
			// published. The template defaults the topic to the message
			// name, so only a producer that moved it needs the value set.
			if topics := producerTopics[inst.message]; len(topics) == 1 && topics[0] != inst.message && !hasSet(st.Set, "topic") {
				st.Set = append(st.Set, llmSet{Key: "topic", Value: topics[0]})
			}
		default:
			st.Why = "moves data point to point"
		}
		plan.Steps = append(plan.Steps, st)
	}

	return planResponse{
		Summary:  plan.Summary,
		Steps:    s.validatePlan(ctx, plan, in.catalog, in.sysRel, in.sysDir, in.tag),
		Model:    j.model,
		Warnings: warnings,
		Trace:    j.trace(),
		Usage:    j.usage,
	}, nil
}

// discover reads the yes/no candidates under prefix: yes is kept, no is
// dropped, and a borderline answer becomes a clarification.
func (s *apiServer) discover(j *jevSession, clar *clarifications, ans map[string]string, prefix string, keys []string, ask string) []string {
	var out []string
	for _, k := range keys {
		id := prefix + "." + k
		switch j.yes(id, ans) {
		case vYes:
			out = append(out, k)
			j.mark(id, "accepted")
		case vNo:
			j.mark(id, "rejected")
		default:
			j.mark(id, "clarify")
			clar.add(yesNo(id, fmt.Sprintf(ask, channelLabel(k))))
		}
	}
	return out
}

// word reads a naming pick. Below the floor it asks, offering Jev's top
// candidates; an escape answer yields "".
func (s *apiServer) word(j *jevSession, clar *clarifications, ans map[string]string, id, question string, escapes ...string) string {
	if _, asked := j.asked[id]; !asked {
		if v := ans[id]; v != "" {
			return v
		}
		clar.add(clarification{ID: id, Kind: "text", Question: question})
		return ""
	}
	v, ok := j.pick(id, ans)
	if !ok {
		j.mark(id, "clarify")
		clar.add(clarification{ID: id, Kind: "choice", Question: question, Options: j.ranked(id, 4, escapes...)})
		return ""
	}
	j.mark(id, "accepted")
	if contains(escapes, v) {
		return ""
	}
	return v
}

// paramQuestions adds, for every template, whether each parameter is stated
// and what it is stated as. Asked speculatively in round 1 — a question
// for a template the plan does not select costs a few tokens, a second
// round trip costs latency.
func paramQuestions(qs map[string]jevQuestion, prompt string, templates []catalogTemplate) {
	for _, ct := range templates {
		for _, p := range ct.Parameters {
			if p.Name == "organization" {
				continue
			}
			f := ct.fields[p.Name]
			id := "param." + ct.Name + "." + p.Name
			label := p.Name
			if f.Title != "" {
				label = f.Title
			}
			desc := truncate(f.Description, 160)
			qs[id+".set"] = noulQ(fmt.Sprintf("Does `request` explicitly state a value for %q (%s)?", label, desc),
				"the request states a value for it", "the request does not mention it")
			switch {
			case f.Type == "boolean":
				qs[id+".value"] = noulQ(fmt.Sprintf("Does `request` ask for %q to be turned on? (%s)", label, desc),
					"it asks for it to be on", "it asks for it to be off")
			case len(f.Enum) > 0:
				opts := make([]option, 0, len(f.Enum))
				for _, e := range f.Enum {
					opts = append(opts, option{key: fmt.Sprint(e)})
				}
				qs[id+".value"] = choiceQ(fmt.Sprintf("Which value does `request` give for %q?", label), opts)
			default:
				cands := literalCandidates(prompt, f)
				if len(cands) == 0 {
					continue
				}
				opts := make([]option, 0, len(cands)+1)
				for _, c := range cands {
					opts = append(opts, option{key: c})
				}
				qs[id+".value"] = choiceQ(fmt.Sprintf("Which span of `request` is the value for %q?", label),
					append(opts, option{"none", "none of these is the value"}))
			}
		}
	}
}

// resolveParams applies the parameter rules: an explicit value is used, an
// omitted one falls to its declared default, and a required value without
// a default — or an explicit value Jev cannot pin down — is asked.
func (s *apiServer) resolveParams(j *jevSession, clar *clarifications, ans map[string]string, ct catalogTemplate, prompt string) []llmSet {
	var out []llmSet
	for _, p := range ct.Parameters {
		if p.Name == "organization" {
			continue
		}
		f := ct.fields[p.Name]
		id := "param." + ct.Name + "." + p.Name
		if v, ok := ans[id]; ok && v != "" {
			out = append(out, llmSet{Key: p.Name, Value: v})
			continue
		}
		stated := j.yes(id+".set", ans) == vYes
		if !stated {
			j.mark(id+".set", "default")
			j.mark(id+".value", "unused")
			if f.Required && f.Default == nil {
				clar.add(clarification{ID: id, Kind: "text", Pattern: f.Pattern,
					Question: fmt.Sprintf("%s requires %q: %s", ct.Name, p.Name, truncate(f.Description, 160))})
			}
			continue
		}
		j.mark(id+".set", "accepted")
		vid := id + ".value"
		if _, asked := j.asked[vid]; !asked {
			clar.add(clarification{ID: id, Kind: "text", Pattern: f.Pattern,
				Question: fmt.Sprintf("The request sets %q for %s; which value? (%s)", p.Name, ct.Name, truncate(f.Description, 120))})
			continue
		}
		if f.Type == "boolean" {
			switch j.yes(vid, ans) {
			case vYes:
				j.mark(vid, "accepted")
				out = append(out, llmSet{Key: p.Name, Value: "true"})
			case vNo:
				j.mark(vid, "accepted")
				out = append(out, llmSet{Key: p.Name, Value: "false"})
			default:
				j.mark(vid, "clarify")
				clar.add(clarification{ID: id, Kind: "choice", Question: fmt.Sprintf("Should %q be on for %s?", p.Name, ct.Name),
					Options: []clarifOption{{Value: "true"}, {Value: "false"}}})
			}
			continue
		}
		v, ok := j.pick(vid, ans)
		if !ok || v == "none" {
			j.mark(vid, "clarify")
			clar.add(clarification{ID: id, Kind: "text", Pattern: f.Pattern,
				Question: fmt.Sprintf("Which value should %q have for %s? (%s)", p.Name, ct.Name, truncate(f.Description, 120))})
			continue
		}
		j.mark(vid, "accepted")
		out = append(out, llmSet{Key: p.Name, Value: v})
	}
	return out
}

// samePairs asks, for each pair of discovered keys, whether they name the
// same endpoint ("blob" and "archive" in one request often do).
func samePairs(qs map[string]jevQuestion, prefix string, keys []string, what string) {
	for a := 0; a < len(keys); a++ {
		for b := a + 1; b < len(keys); b++ {
			qs["same."+prefix+"."+keys[a]+"."+keys[b]] = noulQ(
				fmt.Sprintf("In `request`, do %q and %q describe the same %s?", channelLabel(keys[a]), channelLabel(keys[b]), what),
				"they are one "+what+" described two ways", "they are two different "+what+"s")
		}
	}
}

// merge drops the later key of each pair Jev says is the same, keeping a
// channel key over a noun so names stay channel-based.
func merge(j *jevSession, ans map[string]string, prefix string, keys []string) []string {
	drop := map[string]bool{}
	for a := 0; a < len(keys); a++ {
		for b := a + 1; b < len(keys); b++ {
			id := "same." + prefix + "." + keys[a] + "." + keys[b]
			if _, asked := j.asked[id]; !asked {
				continue
			}
			if j.yes(id, ans) != vYes {
				j.mark(id, "rejected")
				continue
			}
			j.mark(id, "accepted")
			if isChannel(keys[b]) && !isChannel(keys[a]) {
				drop[keys[a]] = true
			} else {
				drop[keys[b]] = true
			}
		}
	}
	var out []string
	for _, k := range keys {
		if !drop[k] {
			out = append(out, k)
		}
	}
	return out
}

// composeMessage names a new message: the data word, or for a request that
// lists several kinds of documents, one raw message from the subject — the
// shape an intake publishes before routing splits it.
func composeMessage(subject, data string) string {
	switch {
	case data != "" && data != "mixed":
		return xstrings.ToKebabCase(data)
	case subject != "":
		return "raw-" + xstrings.ToKebabCase(subject) + "-message"
	}
	return "raw-message"
}

type existingMessage struct{ name, publisher, topic string }

func existingMessages(blocks []existingBlock) []existingMessage {
	var out []existingMessage
	seen := map[string]bool{}
	for _, b := range blocks {
		if b.Publishes == "" || seen[b.Publishes] {
			continue
		}
		seen[b.Publishes] = true
		out = append(out, existingMessage{name: b.Publishes, publisher: b.Dir, topic: b.Topic})
	}
	return out
}

// producerTopics maps each message to the distinct topics its producers
// publish it on — existing records and planned extractors alike.
func producerTopics(existing []existingBlock, instances []jevInstance, params map[string][]llmSet) map[string][]string {
	out := map[string][]string{}
	add := func(msg, topic string) {
		if topic == "" {
			topic = msg
		}
		if !contains(out[msg], topic) {
			out[msg] = append(out[msg], topic)
		}
	}
	for _, b := range existing {
		if b.Publishes != "" {
			add(b.Publishes, b.Topic)
		}
	}
	for _, inst := range instances {
		if inst.kind != template.BlockKindExtractor {
			continue
		}
		topic := ""
		for _, kv := range params[inst.template] {
			if kv.Key == "topic" {
				topic = kv.Value
			}
		}
		add(inst.message, topic)
	}
	return out
}

func jevSummary(instances []jevInstance, sources, dests []string) string {
	var parts []string
	if len(sources) > 0 {
		var labels []string
		for _, s := range sources {
			labels = append(labels, channelLabel(s))
		}
		msg := ""
		for _, i := range instances {
			if i.kind == template.BlockKindExtractor {
				msg = i.message
				break
			}
		}
		parts = append(parts, fmt.Sprintf("%d extractor(s) (%s) publish %s", len(sources), strings.Join(labels, ", "), msg))
	}
	if len(dests) > 0 {
		var labels []string
		for _, d := range dests {
			labels = append(labels, channelLabel(d))
		}
		parts = append(parts, fmt.Sprintf("%d loader(s) deliver to %s", len(dests), strings.Join(labels, ", ")))
	}
	for _, i := range instances {
		if i.kind == "transactional-integration" {
			parts = append(parts, "a transactional integration moves data point to point")
		}
	}
	return "Plan: " + strings.Join(parts, "; ") + "."
}

func yesNo(id, question string) clarification {
	return clarification{ID: id, Kind: "choice", Question: question,
		Options: []clarifOption{{Value: "yes"}, {Value: "no"}}}
}

func kindLabel(kind string) string {
	switch kind {
	case template.BlockKindExtractor:
		return "component that brings data in"
	case template.BlockKindLoader:
		return "component that delivers data out"
	case "transactional-integration":
		return "point-to-point job"
	}
	return kind
}

func channelKeys() []string {
	out := make([]string, len(channels))
	for i, c := range channels {
		out[i] = c.key
	}
	return out
}

func isChannel(k string) bool {
	for _, c := range channels {
		if c.key == k {
			return true
		}
	}
	return false
}

func channelLabel(k string) string {
	for _, c := range channels {
		if c.key == k {
			return c.label
		}
	}
	return k
}

func sortedTemplates(catalog map[string]catalogTemplate) []catalogTemplate {
	out := make([]catalogTemplate, 0, len(catalog))
	for _, ct := range catalog {
		out = append(out, ct)
	}
	sort.Slice(out, func(a, b int) bool { return out[a].Name < out[b].Name })
	return out
}

func hasSet(sets []llmSet, key string) bool {
	for _, kv := range sets {
		if kv.Key == key {
			return true
		}
	}
	return false
}

