			out = append(out, fmt.Sprintf("%s is published on several topics (%s); subscribers can only listen on one", m, strings.Join(producers[m], ", ")))
		}
	}
	for _, st := range steps {
		if st.Request == nil || st.Request.Subscribe == "" {
			continue
		}
		msg := st.Request.Subscribe
		topic, _ := st.Values["topic"].(string)
		if topic == "" {
			topic = msg
		}
		switch topics := producers[msg]; {
		case len(topics) == 0:
			out = append(out, fmt.Sprintf("%s subscribes to %s, which nothing in this system publishes", st.Request.Name, msg))
		case !contains(topics, topic):
			out = append(out, fmt.Sprintf("%s listens on %s, but %s is published on %s", st.Request.Name, topic, msg, strings.Join(topics, ", ")))
		}
	}
	return out
}

