package dashboard

import (
	"context"
	"encoding/json"
	"net/http"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
)

// scriptedJev answers yes/no questions from nouls (default: a clear no)
// and choices from choices (default: "none"), recording each request.
type scriptedJev struct {
	nouls   map[string]float64
	choices map[string]string
	seen    []jevRequest
}

func (f *scriptedJev) ask(_ context.Context, req jevRequest) (jevResponse, error) {
	f.seen = append(f.seen, req)
	resp := jevResponse{Model: "jev-test", Answers: map[string]jevAnswer{}}
	for id, q := range req.Questions {
		if q.Type == "noul" {
			p, ok := f.nouls[id]
			if !ok {
				p = 0.02
			}
			resp.Answers[id] = jevAnswer{Type: "noul", Noul: p}
			continue
		}
		c, ok := f.choices[id]
		if !ok {
			c = "none"
		}
		resp.Answers[id] = jevAnswer{Type: "choice", Choice: c, Confidence: 1, Probabilities: map[string]float64{c: 1}}
	}
	resp.Usage.InputTokens, resp.Usage.OutputTokens = 100, 10
	return resp, nil
}

func jevHandler(t *testing.T, root string, jev *scriptedJev, org string) http.Handler {
	t.Helper()
	p := templateProviders(newAssistantLibrary(t).Source(t))
	p.jev = &jevProvider{model: "jev-latest", ask: jev.ask}
	h, api, err := newHandler(root, "test", p)
	if err != nil {
		t.Fatal(err)
	}
	api.organization = org
	return h
}

func planJev(t *testing.T, h http.Handler, prompt string, answers map[string]string) planResponse {
	t.Helper()
	body, _ := json.Marshal(map[string]any{"prompt": prompt, "engine": "jev", "answers": answers})
	return decodePlanResponse(t, postJSON(t, h, "/api/assistant/plan", string(body)))
}

const intakePrompt = "Partners send orders, invoices and complaints as EDI files over SFTP and as JSON over HTTP. Set up the intake."

// intakeJev is Jev reading the intake prompt: one kind, two channels, a
// subject, and a data word that says several document kinds are mixed.
func intakeJev() *scriptedJev {
	return &scriptedJev{
		nouls:   map[string]float64{"tpl.extractor": 0.99, "src.sftp": 0.97, "src.http": 0.94},
		choices: map[string]string{"subject": "partner", "data": "mixed"},
	}
}

func commands(steps []planStep) []string {
	out := make([]string, len(steps))
	for i, s := range steps {
		out[i] = s.Command
		if s.Error != "" {
			out[i] += " ERROR " + s.Error
		}
	}
	return out
}

func TestJevPlansOneIntakePerChannel(t *testing.T) {
	jev := intakeJev()
	got := planJev(t, jevHandler(t, t.TempDir(), jev, "Acme"), intakePrompt, nil)

	want := []string{
		"intropy int create extractor -n SftpPartnerIntake --publishes raw-partner-message --template-version v1.4.0 --no-input",
		"intropy int create extractor -n HttpPartnerIntake --publishes raw-partner-message --template-version v1.4.0 --no-input",
	}
	cmds := commands(got.Steps)
	if len(cmds) != 3 {
		t.Fatalf("steps = %v", cmds)
	}
	for i, w := range want {
		// The configured organization is appended by validation, as Berget
		// plans get it.
		w = strings.Replace(w, " --template-version", " --set organization=Acme --template-version", 1)
		if cmds[i] != w {
			t.Errorf("step %d =\n %s\nwant\n %s", i, cmds[i], w)
		}
	}
	if got.Engine != "jev" || got.Usage.Calls != 2 {
		t.Errorf("engine %q, usage %+v: want two calls (fan-out, then the merge round)", got.Engine, got.Usage)
	}
	// Every unstated parameter fell to its default.
	for _, d := range got.Trace {
		if strings.HasSuffix(d.ID, ".set") && d.Outcome != "default" {
			t.Errorf("%s outcome = %s", d.ID, d.Outcome)
		}
	}
}

func TestJevAsksForMissingOrganization(t *testing.T) {
	h := jevHandler(t, t.TempDir(), intakeJev(), "")

	got := planJev(t, h, intakePrompt, nil)
	if len(got.Steps) != 0 || len(got.Clarifications) != 1 || got.Clarifications[0].ID != "organization" {
		t.Fatalf("plan = %+v", got)
	}

	got = planJev(t, h, intakePrompt, map[string]string{"organization": "Globex"})
	if len(got.Clarifications) != 0 || !strings.Contains(got.Steps[0].Command, "--set organization=Globex") {
		t.Errorf("answered plan = %v", commands(got.Steps))
	}
}

func TestJevAsksAboutBorderlineChannel(t *testing.T) {
	jev := intakeJev()
	jev.nouls["src.email"] = 0.5
	h := jevHandler(t, t.TempDir(), jev, "Acme")

	got := planJev(t, h, intakePrompt, nil)
	if len(got.Clarifications) != 1 || got.Clarifications[0].ID != "src.email" {
		t.Fatalf("clarifications = %+v", got.Clarifications)
	}
	got = planJev(t, h, intakePrompt, map[string]string{"src.email": "no"})
	if len(got.Steps) != 3 {
		t.Errorf("steps = %v", commands(got.Steps))
	}
}

func TestJevNoSuitableTemplate(t *testing.T) {
	jev := &scriptedJev{nouls: map[string]float64{"tpl.none": 0.9, "tpl.loader": 0.5}}
	got := planJev(t, jevHandler(t, t.TempDir(), jev, "Acme"), "Generate a monthly PDF report.", nil)
	if len(got.Steps) != 0 || len(got.Clarifications) != 0 || !strings.Contains(got.Summary, "no suitable template") {
		t.Errorf("plan = %+v", got)
	}
}

func TestJevExplicitParameter(t *testing.T) {
	jev := &scriptedJev{
		nouls: map[string]float64{
			"tpl.extractor": 0.97, "src.sftp": 0.98,
			"param.extractor.topic.set": 0.97,
		},
		choices: map[string]string{"subject": "acme", "data": "invoice", "param.extractor.topic.value": "finance.inbound"},
	}
	got := planJev(t, jevHandler(t, t.TempDir(), jev, "Acme"), "Acme receives invoices over SFTP. Publish them on topic finance.inbound.", nil)
	if len(got.Steps) == 0 || !strings.Contains(got.Steps[0].Command, "--publishes invoice --set topic=finance.inbound") {
		t.Errorf("steps = %v", commands(got.Steps))
	}
	// The value question offered the request's literal span.
	q := jev.seen[0].Questions["param.extractor.topic.value"]
	if !strings.Contains(string(q.Criteria), `"finance.inbound"`) {
		t.Errorf("topic candidates = %s", q.Criteria)
	}
}

// A request about a message the system already receives plans no second
// intake, and its subscribers follow the producer onto its topic.
func TestJevDeliversExistingMessageOnItsTopic(t *testing.T) {
	root := t.TempDir()
	writeScaffoldRecord(t, filepath.Join(root, "sftp-intake"), `{
  "schemaVersion": 1, "template": "extractor", "owner": "o", "repo": "r", "version": "v1",
  "values": {"appId": "sftp-intake", "publishes": "raw-partner-message", "topic": "inbound.raw"},
  "blockKind": "extractor", "dataFlow": "in"
}`)
	jev := &scriptedJev{
		nouls: map[string]float64{
			"tpl.extractor": 0.97, "tpl.loader": 0.93,
			"srcsys.partner": 0.97, "dstsys.erp": 0.98,
		},
		choices: map[string]string{"subject": "partner", "reuse": "raw-partner-message"},
	}
	got := planJev(t, jevHandler(t, root, jev, "Acme"), "Deliver the incoming partner messages to our ERP.", nil)

	cmds := commands(got.Steps)
	want := "intropy int create loader -n ErpPartnerLoader --subscribe raw-partner-message --set topic=inbound.raw --set organization=Acme --template-version v1.4.0 --no-input"
	if len(cmds) != 2 || cmds[0] != want {
		t.Fatalf("steps =\n %s\nwant first\n %s", strings.Join(cmds, "\n "), want)
	}
	if len(got.Warnings) != 1 || !strings.Contains(got.Warnings[0], "already arrives") {
		t.Errorf("warnings = %v", got.Warnings)
	}
}

func TestCrossCheckFlagsUnpublishedSubscription(t *testing.T) {
	steps := []planStep{{Request: &createRequest{Name: "ErpLoader", Subscribe: "order"}, Values: map[string]any{}}}
	got := crossCheck(steps, nil)
	if len(got) != 1 || !strings.Contains(got[0], "nothing in this system publishes") {
		t.Errorf("warnings = %v", got)
	}
}

func TestChoiceKeepsOptionOrder(t *testing.T) {
	q := choiceQ("pick", []option{{key: "zeta"}, {key: "alpha", desc: "first letter"}, {key: "none", desc: "neither"}})
	if string(q.Criteria) != `{"zeta":null,"alpha":"first letter","none":"neither"}` {
		t.Errorf("criteria = %s", q.Criteria)
	}
}

func TestRequestWordCandidates(t *testing.T) {
	if got := requestNouns(intakePrompt); !reflect.DeepEqual(got, []string{"partner", "order", "invoice", "complaint"}) {
		t.Errorf("nouns = %v", got)
	}
	if got := properNouns("Acme receives invoices. Partners at Contoso send them via SFTP."); !reflect.DeepEqual(got, []string{"Acme", "Partners", "Contoso"}) {
		t.Errorf("proper nouns = %v", got)
	}
}

