head='''import { useEffect, useMemo, useRef, useState } from 'react'
import {
  api,
  type AssistantPlan,
  type AssistantStatus,
  type Clarification,
  type Decision,
  type EngineUsage,
  type PlanStep,
  type TopologyComponent,
} from '../api'

interface Props {
  /** Root-relative system directory the plan targets ("." for the root). */
  system: string
  /** The components not yet created, for the canvas to draw as planned. */
  onPreview: (components: TopologyComponent[]) => void
  /** A step changed the workspace: a scaffold rendered or the host assembled. */
  onApplied: (step: PlanStep) => void
}

type StepState = 'pending' | 'running' | 'done' | 'failed'

interface StepRun {
  state: StepState
  output: string[]
}

const EXAMPLE =
  'Partners send orders, invoices and complaints as EDI files over SFTP and as JSON over HTTP. Set up the intake.'

const ENGINE_KEY = 'intropy.assistant.engine'

// AssistantPanel turns a prose request into the CLI calls that build it and
// lists them beside the canvas. Planning is read-only; Apply runs each step
// through the same endpoints the create drawer and the host banner use, in
// order, and stops at the first failure so later steps never run against a
// workspace the plan did not expect.
//
// Two engines plan the same request for comparison: Berget generates the
// plan, Jev decides it question by question. A Jev plan may come back as
// clarifications instead; answering them plans again with the answers, so
// the server stays stateless.
export function AssistantPanel({ system, onPreview, onApplied }: Props) {
  const [status, setStatus] = useState<AssistantStatus | null>(null)
  const [engine, setEngine] = useState<string>(() => {
    try {
      return localStorage.getItem(ENGINE_KEY) ?? ''
    } catch {
      return ''
    }
  })
  const [prompt, setPrompt] = useState('')
  const [planning, setPlanning] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [plan, setPlan] = useState<AssistantPlan | null>(null)
  // Answers given so far for this prompt, keyed by clarification ID.
  const [answers, setAnswers] = useState<Record<string, string>>({})
  const [runs, setRuns] = useState<Record<string, StepRun>>({})
  const [applying, setApplying] = useState(false)
  const abort = useRef<AbortController | null>(null)

  useEffect(() => {
    api
      .assistantStatus()
      .then(setStatus)
      .catch(() => setStatus({ enabled: false }))
  }, [])

  useEffect(() => () => abort.current?.abort(), [])

  const engines = status?.engines ?? []
  // A remembered engine that is no longer configured falls back to the first.
  const active = engines.find((e) => e.id === engine) ?? engines[0]
  useEffect(() => {
    if (!active) return
    try {
      localStorage.setItem(ENGINE_KEY, active.id)
    } catch {
      // storage unavailable: the choice lasts for this page only
    }
  }, [active])

  // The canvas draws every planned component that has not rendered yet; a
  // rendered one shows up as a scaffolded ghost through the normal refresh.
  useEffect(() => {
    const pending = (plan?.steps ?? []).filter(
      (s) => s.preview && !s.error && runs[s.id]?.state !== 'done',
    )
    onPreview(pending.map((s) => s.preview!))
  }, [plan, runs, onPreview])

  const invalid = useMemo(() => (plan?.steps ?? []).filter((s) => s.error).length, [plan])
  const allDone =
    !!plan && plan.steps.length > 0 && plan.steps.every((s) => runs[s.id]?.state === 'done')
  const pendingQuestions = plan?.clarifications ?? []

  const run = (given: Record<string, string>) => {
    const text = prompt.trim()
    if (!text || planning) return
    abort.current?.abort()
    const ctl = new AbortController()
    abort.current = ctl
    setPlanning(true)
    setError(null)
    setRuns({})
    api
      .plan({ prompt: text, system, engine: active?.id, answers: given }, ctl.signal)
      .then(setPlan)
      .catch((e: unknown) => {
        if (!ctl.signal.aborted) setError(e instanceof Error ? e.message : String(e))
      })
      .finally(() => {
        if (abort.current === ctl) setPlanning(false)
      })
  }

  // A new request starts from no answers; the previous plan stays visible
  // until the new one lands, so switching engines compares side by side.
  const submit = () => {
    setAnswers({})
    setPlan(null)
    run({})
  }

  const answer = (more: Record<string, string>) => {
    const next = { ...answers, ...more }
    setAnswers(next)
    run(next)
  }

  const setRun = (id: string, r: StepRun) => setRuns((all) => ({ ...all, [id]: r }))

  const apply = async () => {
    if (!plan || invalid > 0 || applying) return
    setApplying(true)
    for (const step of plan.steps) {
      if (runs[step.id]?.state === 'done') continue
      setRun(step.id, { state: 'running', output: [] })
      try {
        const output = await runStep(step)
        setRun(step.id, { state: 'done', output })
        onApplied(step)
      } catch (e) {
        setRun(step.id, { state: 'failed', output: [e instanceof Error ? e.message : String(e)] })
        break
      }
    }
    setApplying(false)
  }

  const discard = () => {
    abort.current?.abort()
    setPlan(null)
    setAnswers({})
    setRuns({})
    setError(null)
  }

  if (status && !status.enabled) {
    return (
      <aside className="ai-panel">
        <div className="ai-head">
          <span className="ai-title">Assistant</span>
        </div>
        <p className="ai-muted">
          Set <code>BERGET_API_KEY</code> (Berget AI) or <code>TYPESAFE_API_KEY</code> (TypeSafe
          Jev) and restart <code>intropy dashboard</code> to plan from a description.
        </p>
      </aside>
    )
  }

  return (
    <aside className="ai-panel">
      <div className="ai-head">
        <span className="ai-title">Assistant</span>
        {engines.length > 1 ? (
          <div className="ai-engines" role="radiogroup" aria-label="Planning engine">
            {engines.map((e) => (
              <button
                key={e.id}
                type="button"
                role="radio"
                aria-checked={active?.id === e.id}
                className={`ai-engine${active?.id === e.id ? ' active' : ''}`}
                onClick={() => setEngine(e.id)}
                disabled={planning || applying}
                title={e.model}
              >
                {e.label}
              </button>
            ))}
          </div>
        ) : (
          active && (
            <span className="ai-model" title={active.model}>
              {active.label} · {active.model.split('/').pop()}
            </span>
          )
        )}
      </div>
      <form
        className="ai-prompt"
        onSubmit={(e) => {
          e.preventDefault()
          submit()
        }}
      >
        <label htmlFor="ai-prompt-input" className="ai-label">
          Describe what the system should do
        </label>
        <textarea
          id="ai-prompt-input"
          autoFocus
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
              e.preventDefault()
              submit()
            }
          }}
          placeholder={EXAMPLE}
          rows={4}
          disabled={applying}
        />
        <div className="ai-prompt-actions">
          <span className="ai-hint">⌘↵ to plan</span>
          {!prompt && (
            <button type="button" className="ai-link" onClick={() => setPrompt(EXAMPLE)}>
              use example
            </button>
          )}
          <button
            type="submit"
            className="ai-primary"
            disabled={!prompt.trim() || planning || applying}
            title="Plan (⌘↵)"
          >
            {planning ? 'Planning…' : 'Plan'}
          </button>
        </div>
      </form>

      {planning && (
        <p className="ai-muted ai-pulse">
          asking {active ? `${active.label} (${active.model.split('/').pop()})` : 'the model'}…
        </p>
      )}
      {error && <div className="banner error">{error}</div>}

      {plan && !planning && (
        <div className="ai-plan">
          <UsageLine plan={plan} />
          {plan.summary && <p className="ai-summary">{plan.summary}</p>}
          {pendingQuestions.length > 0 && (
            <Clarifications
              key={pendingQuestions.map((q) => q.id).join('|')}
              questions={pendingQuestions}
              onAnswer={answer}
            />
          )}
          {pendingQuestions.length === 0 && plan.steps.length === 0 && (
            <p className="ai-muted">no steps planned</p>
          )}
          {plan.warnings && plan.warnings.length > 0 && (
            <ul className="ai-warnings">
              {plan.warnings.map((w) => (
                <li key={w}>{w}</li>
              ))}
            </ul>
          )}
          {plan.steps.length > 0 && (
            <>
              <ol className="ai-steps">
                {plan.steps.map((s) => (
                  <Step key={s.id} step={s} run={runs[s.id]} version={plan.version} />
                ))}
              </ol>
              {invalid > 0 && (
                <p className="ai-error-note">
                  {invalid === 1 ? '1 step does' : `${invalid} steps do`} not validate against{' '}
                  templates {plan.version}; rephrase the request and plan again
                </p>
              )}
              <div className="ai-actions">
                <button
                  type="button"
                  className="ai-primary"
                  onClick={apply}
                  disabled={invalid > 0 || applying || allDone}
                >
                  {applying ? 'Applying…' : allDone ? 'Applied' : `Apply ${plan.steps.length} steps`}
                </button>
                <CopyButton
                  text={plan.steps.map((s) => s.command).join('\\n')}
                  label="Copy as script"
                />
                <button
                  type="button"
                  className="ai-secondary"
                  onClick={discard}
                  disabled={applying}
                >
                  Discard
                </button>
              </div>
            </>
          )}
          {Object.keys(answers).length > 0 && (
            <p className="ai-muted ai-answers">
              answered:{' '}
              {Object.entries(answers)
                .map(([k, v]) => `${k} = ${v}`)
                .join(', ')}
            </p>
          )}
          {plan.trace && plan.trace.length > 0 && <Trace decisions={plan.trace} />}
        </div>
      )}
    </aside>
  )
}

// UsageLine is the plan's cost, the numbers an engine comparison turns on.
function UsageLine({ plan }: { plan: AssistantPlan }) {
  const u: EngineUsage = plan.usage
  const secs = (u.latencyMs / 1000).toFixed(u.latencyMs < 10000 ? 2 : 1)
  return (
    <p className="ai-usage">
      {plan.engine === 'jev' ? 'Jev' : 'Berget'} · {plan.model.split('/').pop()} · {u.calls}{' '}
      {u.calls === 1 ? 'call' : 'calls'} · {u.inputTokens.toLocaleString()} in /{' '}
      {u.outputTokens.toLocaleString()} out · {secs}s
    </p>
  )
}

// Clarifications asks the engine's open questions in one form: a choice
// lists the ranked options (with the engine's probability), a text question
// takes a value. Submitting plans again with every answer given.
function Clarifications({
  questions,
  onAnswer,
}: {
  questions: Clarification[]
  onAnswer: (answers: Record<string, string>) => void
}) {
  const [values, setValues] = useState<Record<string, string>>(() =>
    Object.fromEntries(questions.map((q) => [q.id, ''])),
  )
  const complete = questions.every((q) => values[q.id]?.trim())
  const set = (id: string, v: string) => setValues((all) => ({ ...all, [id]: v }))
  return (
    <form
      className="ai-clarify"
      onSubmit={(e) => {
        e.preventDefault()
        if (complete) onAnswer(Object.fromEntries(Object.entries(values).map(([k, v]) => [k, v.trim()])))
      }}
    >
      {questions.map((q) => (
        <fieldset key={q.id} className="ai-question">
          <legend>{q.question}</legend>
          {q.kind === 'choice' && q.options && q.options.length > 0 ? (
            <div className="ai-options">
              {q.options.map((o) => (
                <label key={o.value} className={values[q.id] === o.value ? 'chosen' : undefined}>
                  <input
                    type="radio"
                    name={q.id}
                    value={o.value}
                    checked={values[q.id] === o.value}
                    onChange={() => set(q.id, o.value)}
                  />
                  <span>{o.label ? `${o.value} — ${o.label}` : o.value}</span>
                  {o.probability !== undefined && o.probability > 0 && (
                    <span className="ai-prob">{Math.round(o.probability * 100)}%</span>
                  )}
                </label>
              ))}
            </div>
          ) : (
            <input
              type="text"
              className="ai-text-answer"
              value={values[q.id]}
              onChange={(e) => set(q.id, e.target.value)}
              pattern={q.pattern}
              aria-label={q.question}
            />
          )}
        </fieldset>
      ))}
      <div className="ai-actions">
        <button type="submit" className="ai-primary" disabled={!complete}>
          Answer and plan
        </button>
      </div>
    </form>
  )
}

// Trace lists every engine decision: what was asked, the answer with its
// confidence, and what the plan did with it. Unused speculative questions
// are folded away by default — they are cost, not reasoning.
function Trace({ decisions }: { decisions: Decision[] }) {
  const [showUnused, setShowUnused] = useState(false)
  const shown = showUnused ? decisions : decisions.filter((d) => d.outcome !== 'unused')
  const unused = decisions.length - decisions.filter((d) => d.outcome !== 'unused').length
  return (
    <details className="ai-trace">
      <summary>
        Decisions ({decisions.length - unused}
        {unused > 0 ? ` + ${unused} unused` : ''})
      </summary>
      {unused > 0 && (
        <button type="button" className="ai-link" onClick={() => setShowUnused((v) => !v)}>
          {showUnused ? 'hide unused' : 'show unused'}
        </button>
      )}
      <table>
        <thead>
          <tr>
            <th>Question</th>
            <th>Answer</th>
            <th>Conf.</th>
            <th>Outcome</th>
          </tr>
        </thead>
        <tbody>
          {shown.map((d) => (
            <tr key={d.id} className={`ai-outcome-${d.outcome.split(' ')[0]}`}>
              <td title={d.question}>
                <code>{d.id}</code>
              </td>
              <td>{d.answer}</td>
              <td>{d.confidence.toFixed(2)}</td>
              <td>{d.outcome}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </details>
  )
}

