package dashboard

import (
	"context"
	"fmt"
	"sort"
	"strings"

	"github.com/huandu/xstrings"
	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/xregistry"
)

// The registry stage grounds a plan in the xRegistry: instead of composing
// message names from the request's words, Jev selects the message the
// request is about and the endpoint the data goes to from the registry's
// own entries — a closed set, which is what Jev decides well — and the plan
// wires components to the selected message's real channel and pinned
// schema. Each selection has three outcomes: a match, "no match" (the
// explicit none option), and "ambiguous" (confidence below the floor, or a
// runner-up too close to the winner), which is asked back.

// maxRegistryCandidates keeps a registry choice inside Jev's 255-option
// limit with room for the escape options. A larger registry is narrowed by
// word overlap with the request first.
const maxRegistryCandidates = 200

// registryMessage is one registry message with the joins a plan needs.
type registryMessage struct {
	ID          string
	Group       string
	Name        string
	Description string
	// Topic is the producer's topic when exactly one producer channel
	// exists; a message without one cannot be subscribed to as external.
	Topic         string
	Producers     []registryEndpoint
	DataSchema    string
	DataSchemaURL string
}

type registryEndpoint struct {
	ID          string
	Name        string
	Description string
	Usage       []string
	Channel     string
	Groups      []string
}

// registryCatalog is the registry as the planner sees it.
type registryCatalog struct {
	url       string
	messages  []registryMessage
	endpoints []registryEndpoint
}

// registryContract is one selected registry message in the plan response:
// what the plan subscribes to or delivers, with the schema version pinned.
type registryContract struct {
	Role          string   `json:"role"` // source or destination
	Message       string   `json:"message"`
	Name          string   `json:"name,omitempty"`
	Group         string   `json:"group"`
	DataSchema    string   `json:"dataschema,omitempty"`
	DataSchemaURL string   `json:"dataschemaurl,omitempty"`
	Topic         string   `json:"topic,omitempty"`
	Producers     []string `json:"producers,omitempty"`
}

// loadRegistry fetches the export and joins it into a catalog. A registry
// that cannot be read leaves the plan registry-free with a warning: the
// request can still be planned from its words.
func (s *apiServer) loadRegistry(ctx context.Context) (*registryCatalog, error) {
	if s.registry == nil {
		return nil, nil
	}
	doc, err := s.registry.Export(ctx)
	if err != nil {
		return nil, err
	}
	cat := &registryCatalog{url: s.registry.BaseURL()}
	for _, e := range doc.Endpoints {
		cat.endpoints = append(cat.endpoints, registryEndpoint{
			ID: e.ID, Name: e.Name, Description: e.Description,
			Usage: e.Usage, Channel: e.Channel, Groups: e.MessageGroups,
		})
	}
	sort.Slice(cat.endpoints, func(a, b int) bool { return cat.endpoints[a].ID < cat.endpoints[b].ID })
	for gid, g := range doc.MessageGroups {
		for mid, m := range g.Messages {
			def := m.DefaultMessage()
			rm := registryMessage{ID: mid, Group: gid}
			if def != nil {
				rm.Name, rm.Description = def.Name, def.Description
			}
			if res, err := xregistry.ResolveMessage(doc, "/messagegroups/"+gid+"/messages/"+mid); err == nil {
				rm.DataSchema, rm.DataSchemaURL = res.DataSchema, res.DataSchemaURL
				if len(res.Channels) == 1 {
					rm.Topic = res.Channels[0].Topic
				}
			}
			for _, e := range cat.endpoints {
				if contains(e.Groups, "/messagegroups/"+gid) && contains(e.Usage, "producer") {
					rm.Producers = append(rm.Producers, e)
				}
			}
			cat.messages = append(cat.messages, rm)
		}
	}
	sort.Slice(cat.messages, func(a, b int) bool { return cat.messages[a].ID < cat.messages[b].ID })
	return cat, nil
}

func (c *registryCatalog) message(id string) *registryMessage {
	for i := range c.messages {
		if c.messages[i].ID == id {
			return &c.messages[i]
		}
	}
	return nil
}

func (c *registryCatalog) endpoint(id string) *registryEndpoint {
	for i := range c.endpoints {
		if c.endpoints[i].ID == id {
			return &c.endpoints[i]
		}
	}
	return nil
}

func (m registryMessage) label() string {
	var producers []string
	for _, p := range m.Producers {
		producers = append(producers, nameOr(p.Name, p.ID))
	}
	d := nameOr(m.Name, m.ID)
	if m.Description != "" {
		d += " — " + truncate(m.Description, 160)
	}
	if len(producers) > 0 {
		d += ". Produced by " + strings.Join(producers, ", ")
	}
	return d
}

func (e registryEndpoint) label() string {
	d := nameOr(e.Name, e.ID)
	if len(e.Usage) > 0 {
		d += " (" + strings.Join(e.Usage, ", ") + ")"
	}
	if e.Description != "" {
		d += " — " + truncate(e.Description, 160)
	}
	return d
}

// registryQuestions adds the registry selections to the fan-out round.
func registryQuestions(qs map[string]jevQuestion, cat *registryCatalog, prompt string) {
	msgs := narrow(cat.messages, prompt, func(m registryMessage) string { return m.ID + " " + m.Name + " " + m.Description })
	eps := narrow(cat.endpoints, prompt, func(e registryEndpoint) string { return e.ID + " " + e.Name + " " + e.Description })
	if len(msgs) > 0 {
		opts := make([]option, 0, len(msgs)+1)
		for _, m := range msgs {
			opts = append(opts, option{key: m.ID, desc: m.label()})
		}
		qs["reg.source"] = choiceQ("Which registry message is the data that `request` wants to take, use or deliver?",
			append(opts, option{"none", "none of these is the data the request is about"}))
		shape := make([]option, 0, len(msgs)+2)
		for _, m := range msgs {
			shape = append(shape, option{key: m.ID, desc: m.label()})
		}
		qs["reg.shape"] = choiceQ("Which registry message describes the shape the data must have where `request` delivers it?",
			append(shape,
				option{"same", "the data is delivered in the shape it arrives in"},
				option{"none", "the request says nothing about the delivered shape"}))
		for _, m := range msgs {
			qs["reg.build."+m.ID] = noulQ(fmt.Sprintf("Does `request` ask to build the component that produces %q, rather than to use it as it is already produced?", nameOr(m.Name, m.ID)),
				"the request asks to create the producer of this data", "the data is already produced and the request uses or delivers it")
		}
	}
	if len(eps) > 0 {
		opts := make([]option, 0, len(eps)+1)
		for _, e := range eps {
			opts = append(opts, option{key: e.ID, desc: e.label()})
		}
		qs["reg.endpoint"] = choiceQ("Which registry endpoint is where `request` wants the data delivered or handled?",
			append(opts, option{"none", "the request names no destination in this list"}))
	}
}

// narrow keeps a registry list inside the Choice option limit, ranking by
// how many request words an entry's text shares when it must cut.
func narrow[T any](list []T, prompt string, text func(T) string) []T {
	if len(list) <= maxRegistryCandidates {
		return list
	}
	words := requestNouns(prompt)
	type scored struct {
		v T
		n int
	}
	ranked := make([]scored, len(list))
	for i, v := range list {
		t := strings.ToLower(text(v))
		for _, w := range words {
			if strings.Contains(t, w) {
				ranked[i].n++
			}
		}
		ranked[i].v = v
	}
	sort.SliceStable(ranked, func(a, b int) bool { return ranked[a].n > ranked[b].n })
	out := make([]T, maxRegistryCandidates)
	for i := range out {
		out[i] = ranked[i].v
	}
	return out
}

// registrySelection is what the registry stage decided.
type registrySelection struct {
	source        *registryMessage
	shape         *registryMessage
	endpoint      *registryEndpoint
	buildProducer bool
	notes         []string
}

// selectRegistry reads the registry answers. A match is used, "none" falls
// back to planning from the request's words, and an ambiguous answer is
// asked back with the registry's own labels.
func (s *apiServer) selectRegistry(j *jevSession, clar *clarifications, ans map[string]string, cat *registryCatalog) registrySelection {
	var sel registrySelection
	if cat == nil {
		return sel
	}
	pick := func(id, question string, label func(string) string) (string, bool) {
		if _, asked := j.asked[id]; !asked {
			return "", false
		}
		if v, ok := ans[id]; ok && v != "" {
			j.mark(id, "answered")
			return v, v != "none"
		}
		a := j.got[id]
		if ambiguous(a) {
			j.mark(id, "clarify")
			opts := j.ranked(id, 4)
			for i := range opts {
				opts[i].Label = label(opts[i].Value)
			}
			clar.add(clarification{ID: id, Kind: "choice", Question: question, Options: opts})
			return "", false
		}
		if a.Choice == "none" {
			j.mark(id, "no match")
			return "", false
		}
		j.mark(id, "accepted")
		return a.Choice, true
	}
	msgLabel := func(v string) string {
		if m := cat.message(v); m != nil {
			return nameOr(m.Name, m.ID)
		}
		return ""
	}
	if v, ok := pick("reg.source", "Which registry message is the request about?", msgLabel); ok {
		sel.source = cat.message(v)
	} else if j.outcome["reg.source"] == "no match" {
		sel.notes = append(sel.notes, "no registry message matched the request; planned a new message")
	}
	if v, ok := pick("reg.endpoint", "Which registry endpoint should the data reach?", func(v string) string {
		if e := cat.endpoint(v); e != nil {
			return nameOr(e.Name, e.ID)
		}
		return ""
	}); ok {
		sel.endpoint = cat.endpoint(v)
	}
	if v, ok := pick("reg.shape", "Which registry message is the shape delivered at the destination?", msgLabel); ok && v != "same" {
		sel.shape = cat.message(v)
	}
	if sel.source != nil {
		id := "reg.build." + sel.source.ID
		if j.yes(id, ans) == vYes {
			j.mark(id, "accepted")
			sel.buildProducer = true
		} else {
			j.mark(id, "rejected")
		}
	}
	// Selected endpoints that only produce cannot receive deliveries.
	if sel.endpoint != nil && !contains(sel.endpoint.Usage, "subscriber") && !contains(sel.endpoint.Usage, "consumer") {
		sel.notes = append(sel.notes, fmt.Sprintf("%s is a producer in the registry, not a destination; named the delivery from the request instead", sel.endpoint.ID))
		sel.endpoint = nil
	}
	return sel
}

// ambiguous applies TypeSafe's two certainty signals to a choice: the
// confidence floor, and a runner-up within half the winner's probability.
func ambiguous(a jevAnswer) bool {
	if a.Confidence < jevAccept {
		return true
	}
	var first, second float64
	for _, p := range a.Probabilities {
		switch {
		case p > first:
			first, second = p, first
		case p > second:
			second = p
		}
	}
	return first > 0 && second >= first/2
}

// contracts lists the selected registry messages for the response.
func (sel registrySelection) contracts() []registryContract {
	var out []registryContract
	add := func(role string, m *registryMessage) {
		if m == nil {
			return
		}
		c := registryContract{Role: role, Message: m.ID, Name: m.Name, Group: m.Group,
			DataSchema: m.DataSchema, DataSchemaURL: m.DataSchemaURL, Topic: m.Topic}
		for _, p := range m.Producers {
			c.Producers = append(c.Producers, p.ID)
		}
		out = append(out, c)
	}
	add("source", sel.source)
	if sel.shape != nil && (sel.source == nil || sel.shape.ID != sel.source.ID) {
		add("destination", sel.shape)
	}
	return out
}

// registryTopics maps each registry message to its producers' topic, for
// the dependency rule that a subscriber listens where its message travels.
func (c *registryCatalog) topics() map[string]string {
	out := map[string]string{}
	if c == nil {
		return out
	}
	for _, m := range c.messages {
		if m.Topic != "" {
			out[m.ID] = m.Topic
		}
	}
	return out
}

// registryPromptSection describes the registry to the generative engine,
// so a Berget plan can wire to it as a Jev plan does.
func registryPromptSection(cat *registryCatalog) string {
	if cat == nil || len(cat.messages) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("\nRegistry (xRegistry) messages — released contracts other systems produce:\n")
	for _, m := range cat.messages {
		fmt.Fprintf(&b, "- %s: %s; topic %q\n", m.ID, m.label(), m.Topic)
	}
	b.WriteString("Registry endpoints:\n")
	for _, e := range cat.endpoints {
		fmt.Fprintf(&b, "- %s: %s\n", e.ID, e.label())
	}
	b.WriteString(`Registry rules:
- When the request's data is a registry message, subscribe to it by its exact id and set topic to its
  registry topic; do not plan an extractor for data a registry endpoint already produces unless the
  request asks to build that producer.
- When the destination is a registry subscriber endpoint, name the loader after the endpoint id in
  PascalCase (kat-product-loader -> KatProductLoader).
`)
	return b.String()
}

func nameOr(name, id string) string {
	if name != "" {
		return name
	}
	return id
}

// endpointName names a component after a registry endpoint id.
func endpointName(id string) string { return xstrings.ToPascalCase(id) }

// registryKey marks a source or destination key that is a registry
// endpoint, so naming and labels use the endpoint rather than a word.
const registryKey = "reg:"

func isRegistryKey(k string) bool       { return strings.HasPrefix(k, registryKey) }
func registryKeyID(k string) string     { return strings.TrimPrefix(k, registryKey) }
func registryKeyFor(id string) string   { return registryKey + id }
func externalTopic(topic string) string { return topic }

var _ = template.DefaultPubsub

