// Delivering a message a registry endpoint produces is one loader: named
// after the registry's subscriber endpoint, on the producer's topic, with
// the schema pinned — and no intake or point-to-point questions.
func TestJevDeliversRegistryMessage(t *testing.T) {
	jev := &scriptedJev{
		nouls:   map[string]float64{"tpl.loader": 0.9, "tpl.extractor": 0.5, "tpl.transactional": 0.5},
		choices: map[string]string{"reg.source": "maxbo.product.export", "reg.endpoint": "kat-product-loader"},
	}
	got := planJev(t, registryJevHandler(t, jev), "Deliver the Perfion product exports to KAT.", nil)

	cmds := commands(got.Steps)
	want := "intropy int create loader -n KatProductLoader --subscribe maxbo.product.export --set topic=product-export-topic --set organization=Maxbo --template-version v1.4.0 --no-input"
	if len(got.Clarifications) != 0 || len(cmds) != 2 || cmds[0] != want {
		t.Fatalf("clarifications %+v\nsteps\n %s\nwant first\n %s", got.Clarifications, strings.Join(cmds, "\n "), want)
	}
	if len(got.Contracts) != 1 || got.Contracts[0].DataSchemaURL == "" || got.Contracts[0].Topic != "product-export-topic" {
		t.Errorf("contracts = %+v", got.Contracts)
	}
	// The registry's producer satisfies the cross-check.
	for _, w := range got.Warnings {
		if strings.Contains(w, "nothing in this system publishes") {
			t.Errorf("warning = %s", w)
		}
	}
	// Producers are not offered as destinations.
	if q := string(jev.seen[0].Questions["reg.endpoint"].Criteria); strings.Contains(q, "kat-productservice") {
		t.Errorf("endpoint options include a producer: %s", q)
	}
}

func TestJevBuildsRegistryProducer(t *testing.T) {
	jev := &scriptedJev{
		nouls:   map[string]float64{"tpl.extractor": 0.9, "reg.build.maxbo.product.export": 0.9},
		choices: map[string]string{"reg.source": "maxbo.product.export"},
	}
	got := planJev(t, registryJevHandler(t, jev), "Build the Perfion extractor that publishes the product exports.", nil)
	cmds := commands(got.Steps)
	if len(cmds) != 2 || !strings.Contains(cmds[0], "extractor -n PerfionExtractor --publishes maxbo.product.export --set topic=product-export-topic") {
		t.Errorf("steps = %v (clarifications %+v)", cmds, got.Clarifications)
	}
}

// An ambiguous registry source is asked alone, ranked, with registry labels.
func TestJevAsksAmbiguousRegistrySourceAlone(t *testing.T) {
	jev := &scriptedJev{nouls: map[string]float64{"tpl.loader": 0.9, "tpl.transactional": 0.5}}
	jev.override = map[string]jevAnswer{"reg.source": {Type: "choice", Choice: "maxbo.catalog.updated", Confidence: 0.4,
		Probabilities: map[string]float64{"maxbo.catalog.updated": 0.55, "maxbo.product.export": 0.3, "none": 0.15}}}
	got := planJev(t, registryJevHandler(t, jev), "Deliver product data to KAT.", nil)
	if len(got.Clarifications) != 1 || got.Clarifications[0].ID != "reg.source" {
		t.Fatalf("clarifications = %+v", got.Clarifications)
	}
	opts := got.Clarifications[0].Options
	if len(opts) < 2 || opts[0].Value != "maxbo.catalog.updated" || opts[0].Label != "Product updated" {
		t.Errorf("options = %+v", opts)
	}
}

func TestJevRegistryNoMatchFallsBackToWords(t *testing.T) {
	jev := intakeJev()
	got := planJev(t, registryJevHandler(t, jev), intakePrompt, nil)
	if len(got.Steps) != 3 || !strings.Contains(got.Steps[0].Command, "--publishes raw-partner-message") {
		t.Errorf("steps = %v", commands(got.Steps))
	}
	found := false
	for _, w := range got.Warnings {
		found = found || strings.Contains(w, "no registry message matched")
	}
	if !found {
		t.Errorf("warnings = %v", got.Warnings)
	}
}
